			"원본 공원은 읽기 전용이라 저장할 수 없습니다.",
			"Parki oryginalne są tylko do odczytu i nie można ich zapisać.",
			"Los parques originales son de solo lectura y no se pueden guardar.",
			"Originalparker är skrivskyddade och kan inte sparas.", "I parchi originali sono di sola lettura e non si possono salvare.", "הפארקים המקוריים לקריאה בלבד ואי אפשר לשמור אותם." },
		[OpenTpwText.ParkSaved] = new[] { "Park saved (OpenTPW save).", "Park gemt (OpenTPW).", "Park opgeslagen (OpenTPW).", "Parc sauvegardé (OpenTPW).", "Park gespeichert (OpenTPW).", "공원 저장 완료 (OpenTPW).", "Park zapisany (zapis OpenTPW).", "Parque guardado (OpenTPW).", "Parken sparad (OpenTPW).", "Parco salvato (salvataggio OpenTPW).", "הפארק נשמר - שמירה של OpenTPW." },
		[OpenTpwText.SaveFailed] = new[] { "Save failed: {0}", "Kunne ikke gemme: {0}", "Opslaan mislukt: {0}", "Échec de la sauvegarde : {0}", "Speichern fehlgeschlagen: {0}", "저장 실패: {0}", "Błąd zapisu: {0}", "Error al guardar: {0}", "Det gick inte att spara: {0}", "Salvataggio non riuscito: {0}", "השמירה נכשלה: {0}" },
		[OpenTpwText.OriginalParkEntry] = new[] { "{0} - original park (read-only)", "{0} - original park (skrivebeskyttet)", "{0} - origineel park (alleen-lezen)", "{0} - parc d'origine (lecture seule)", "{0} - Originalpark (schreibgeschützt)", "{0} - 원본 공원 (읽기 전용)", "{0} - park oryginalny (tylko do odczytu)", "{0} - parque original (solo lectura)", "{0} - originalpark (skrivskyddad)", "{0} - parco originale (sola lettura)", "{0} - פארק מקורי, לקריאה בלבד" },
		[OpenTpwText.SandboxParkEntry] = new[] { "OpenTPW sandbox park", "OpenTPW-sandkassepark", "OpenTPW-zandbakpark", "Parc bac à sable OpenTPW", "OpenTPW-Sandkastenpark", "OpenTPW 샌드박스 공원", "Park testowy OpenTPW", "Parque de pruebas OpenTPW", "OpenTPW-sandlådepark", "Parco libero di OpenTPW", "פארק חופשי של OpenTPW" },
		[OpenTpwText.NewPark] = new[] { "New park", "Ny park", "Nieuw park", "Nouveau parc", "Neuer Park", "새 공원", "Nowy park", "Parque nuevo", "Ny park", "Nuovo parco", "פארק חדש" },
		[OpenTpwText.ContinueSavedPark] = new[] { "Continue saved park", "Fortsæt gemt park", "Opgeslagen park voortzetten", "Continuer le parc sauvegardé", "Gespeicherten Park fortsetzen", "저장한 공원 계속", "Kontynuuj zapisany park", "Continuar parque guardado", "Fortsätt sparad park", "Continua il parco salvato", "המשך פארק שמור" },
		[OpenTpwText.NewProgressConsent] = new[] { "Start new OpenTPW progress with one key? Past profile history is unknown. Existing saved parks remain loadable.", "Start nye OpenTPW-fremskridt med en nøgle? Tidligere profilhistorik er ukendt. Eksisterende gemte parker kan stadig indlæses.", "Nieuwe OpenTPW-voortgang starten met één sleutel? Eerdere profielgeschiedenis is onbekend. Bestaande opgeslagen parken blijven laadbaar.", "Commencer une nouvelle progression OpenTPW avec une clé ? L'historique du profil est inconnu. Les parcs sauvegardés restent accessibles.", "Neuen OpenTPW-Fortschritt mit einem Schlüssel starten? Der bisherige Profilverlauf ist unbekannt. Gespeicherte Parks bleiben ladbar.", "열쇠 하나로 새 OpenTPW 진행을 시작하겠습니까? 이전 프로필 기록은 알 수 없습니다. 저장한 공원은 계속 불러올 수 있습니다.", "Zacząć nowy postęp OpenTPW z jednym kluczem? Poprzednia historia profilu jest nieznana. Zapisane parki można nadal wczytać.", "¿Empezar un nuevo progreso de OpenTPW con una llave? Se desconoce el historial anterior del perfil. Los parques guardados se pueden seguir cargando.", "Starta nya OpenTPW-framsteg med en nyckel? Tidigare profilhistorik är okänd. Befintliga sparade parker kan fortfarande läsas in.", "Iniziare nuovi progressi OpenTPW con una chiave? La cronologia del profilo precedente è sconosciuta. I parchi già salvati restano caricabili.", "להתחיל התקדמות חדשה של OpenTPW עם מפתח אחד? היסטוריית הפרופיל הקודמת אינה ידועה. הפארקים השמורים עדיין ייטענו." },
		[OpenTpwText.StartNewProgress] = new[] { "Start new progress", "Start nye fremskridt", "Nieuwe voortgang starten", "Nouvelle progression", "Neuen Fortschritt starten", "새 진행 시작", "Zacznij nowy postęp", "Empezar nuevo progreso", "Starta nya framsteg", "Inizia nuovi progressi", "התחל התקדמות חדשה" },
		[OpenTpwText.ProgressKeysNeeded] = new[] { "This theme needs {0} keys. You have {1}. Choose Instant Action or load a saved park.", "Dette tema kræver {0} nøgler. Du har {1}. Vælg Instant Action eller indlæs en gemt park.", "Dit thema vereist {0} sleutels. Je hebt er {1}. Kies Instant Action of laad een opgeslagen park.", "Ce thème nécessite {0} clés. Vous en avez {1}. Choisissez Instant Action ou chargez un parc.", "Dieses Thema benötigt {0} Schlüssel. Du hast {1}. Wähle Instant Action oder lade einen Park.", "이 테마에는 열쇠 {0}개가 필요합니다. 현재 {1}개입니다. 인스턴트 액션을 고르거나 저장한 공원을 불러오십시오.", "Ten temat wymaga kluczy: {0}. Masz: {1}. Wybierz Szybką akcję lub wczytaj zapisany park.", "Este tema necesita {0} llaves. Tienes {1}. Elige Acción Instantánea o carga un parque guardado.", "Detta tema kräver {0} nycklar. Du har {1}. Välj Instant Action eller läs in en sparad park.", "Questo tema richiede {0} chiavi. Ne hai {1}. Scegli Azione immediata o carica un parco salvato.", "הנושא הזה דורש {0} מפתחות. יש לך {1}. בחר פעולה מיידית או טען פארק שמור." },
		[OpenTpwText.ProgressModeKept] = new[] { "Your Instant Action progress will not be reset. Choose Instant Action or load a saved park.", "Dine Instant Action-fremskridt nulstilles ikke. Vælg Instant Action eller indlæs en gemt park.", "Je Instant Action-voortgang wordt niet gewist. Kies Instant Action of laad een opgeslagen park.", "Votre progression Instant Action sera conservée. Choisissez Instant Action ou chargez un parc.", "Dein Instant Action-Fortschritt bleibt erhalten. Wähle Instant Action oder lade einen Park.", "인스턴트 액션 진행은 초기화되지 않습니다. 인스턴트 액션을 고르거나 저장한 공원을 불러오십시오.", "Twój postęp w Szybkiej akcji nie zostanie wyzerowany. Wybierz Szybką akcję lub wczytaj zapisany park.", "Tu progreso de Acción Instantánea no se reiniciará. Elige Acción Instantánea o carga un parque guardado.", "Dina Instant Action-framsteg behålls. Välj Instant Action eller läs in en sparad park.", "I tuoi progressi di Azione immediata non verranno azzerati. Scegli Azione immediata o carica un parco salvato.", "ההתקדמות שלך בפעולה מיידית לא תאופס. בחר פעולה מיידית או טען פארק שמור." },
		[OpenTpwText.ProgressActionFailed] = new[] { "The action could not finish. Saved parks are unchanged. Reopen the choice or retry.", "Handlingen kunne ikke fuldføres. Gemte parker er uændrede. Åbn valget igen eller prøv igen.", "De actie kon niet worden voltooid. Opgeslagen parken zijn ongewijzigd. Open de keuze opnieuw of probeer opnieuw.", "Impossible de terminer. Les parcs sauvegardés sont inchangés. Rouvrez le choix ou réessayez.", "Die Aktion konnte nicht beendet werden. Gespeicherte Parks sind unverändert. Öffne die Auswahl erneut oder versuche es noch einmal.", "작업을 끝내지 못했습니다. 저장한 공원은 그대로입니다. 선택을 다시 열거나 다시 시도하십시오.", "Nie udało się wykonać akcji. Zapisane parki się nie zmieniły. Otwórz wybór ponownie lub spróbuj jeszcze raz.", "No se pudo completar la acción. Los parques guardados no han cambiado. Vuelve a abrir la opción o inténtalo de nuevo.", "Åtgärden kunde inte slutföras. Sparade parker är oförändrade. Öppna valet igen eller försök igen.", "L'azione non è stata completata. I parchi salvati non sono cambiati. Riapri la scelta o riprova.", "הפעולה לא הושלמה. הפארקים השמורים לא השתנו. פתח שוב את הבחירה או נסה שוב." },
		[OpenTpwText.ProgressUnsaved] = new[] { "Progress is not saved yet. Earned tickets are kept in memory. Retry before leaving the park.", "Fremskridt er ikke gemt endnu. Optjente billetter er bevaret i hukommelsen. Prøv igen før du forlader parken.", "Voortgang is nog niet opgeslagen. Verdiende tickets blijven in het geheugen. Probeer opnieuw voordat je het park verlaat.", "La progression n'est pas encore sauvegardée. Les tickets gagnés sont conservés en mémoire. Réessayez avant de quitter le parc.", "Der Fortschritt ist noch nicht gespeichert. Verdiente Tickets bleiben im Speicher. Versuche es erneut, bevor du den Park verlässt.", "진행이 아직 저장되지 않았습니다. 얻은 티켓은 메모리에 있습니다. 공원을 나가기 전에 다시 시도하십시오.", "Postęp nie jest jeszcze zapisany. Zdobyte bilety są w pamięci. Spróbuj ponownie przed wyjściem z parku.", "El progreso aún no se ha guardado. Los billetes ganados se mantienen en memoria. Inténtalo de nuevo antes de salir del parque.", "Framstegen är inte sparade ännu. Intjänade biljetter finns kvar i minnet. Försök igen innan du lämnar parken.", "I progressi non sono ancora salvati. I biglietti guadagnati restano in memoria. Riprova prima di lasciare il parco.", "ההתקדמות עדיין לא נשמרה. הכרטיסים שהרווחת שמורים בזיכרון. נסה שוב לפני שתצא מהפארק." },
		[OpenTpwText.ProgressTrackingUnavailable] = new[] { "OpenTPW progress is not tracking this park. Past player history is unknown or uses another mode. Existing saved parks remain playable.", "OpenTPW-fremskridt registrerer ikke denne park. Tidligere spillerhistorik er ukendt eller bruger en anden tilstand. Gemte parker kan stadig spilles.", "OpenTPW-voortgang wordt niet bijgehouden voor dit park. Eerdere spelergeschiedenis is onbekend of gebruikt een andere modus. Opgeslagen parken blijven speelbaar.", "OpenTPW ne suit pas la progression de ce parc. L'historique du joueur est inconnu ou utilise un autre mode. Les parcs sauvegardés restent jouables.", "OpenTPW erfasst den Fortschritt dieses Parks nicht. Der bisherige Verlauf ist unbekannt oder nutzt einen anderen Modus. Gespeicherte Parks bleiben spielbar.", "OpenTPW가 이 공원의 진행을 기록하지 않습니다. 이전 플레이어 기록을 알 수 없거나 다른 모드입니다. 저장한 공원은 계속 할 수 있습니다.", "OpenTPW nie śledzi postępu w tym parku. Historia gracza jest nieznana lub używa innego trybu. Zapisane parki nadal działają.", "OpenTPW no registra el progreso de este parque. Se desconoce el historial anterior del jugador o usa otro modo. Los parques guardados se pueden seguir jugando.", "OpenTPW registrerar inte framsteg för denna park. Tidigare spelarhistorik är okänd eller använder ett annat läge. Sparade parker kan fortfarande spelas.", "I progressi OpenTPW non seguono questo parco. La cronologia del giocatore è sconosciuta o usa un'altra modalità. I parchi salvati restano giocabili.", "ההתקדמות של OpenTPW אינה עוקבת אחרי הפארק הזה. היסטוריית השחקן אינה ידועה או במצב אחר. הפארקים השמורים עדיין ניתנים למשחק." },
		[OpenTpwText.ContinueAutomaticPark] = new[] { "Continue automatic save", "Fortsæt automatisk gemt park", "Automatisch opgeslagen park hervatten", "Continuer la sauvegarde automatique", "Automatischen Spielstand fortsetzen", "자동 저장 계속", "Kontynuuj zapis automatyczny", "Continuar guardado automático", "Fortsätt automatisk sparning", "Continua il salvataggio automatico", "המשך שמירה אוטומטית" },
		[OpenTpwText.AutomaticCheckpointFailed] = new[] { "The automatic save could not finish. Stay in the park or retry.", "Den automatiske gemning mislykkedes. Bliv i parken eller prøv igen.", "Automatisch opslaan is mislukt. Blijf in het park of probeer opnieuw.", "La sauvegarde automatique a échoué. Restez dans le parc ou réessayez.", "Automatisches Speichern fehlgeschlagen. Bleibe im Park oder versuche es erneut.", "자동 저장을 끝내지 못했습니다. 공원에 머물거나 다시 시도하십시오.", "Nie udało się wykonać zapisu automatycznego. Zostań w parku lub spróbuj jeszcze raz.", "No se pudo completar el guardado automático. Quédate en el parque o inténtalo de nuevo.", "Den automatiska sparningen misslyckades. Stanna i parken eller försök igen.", "Il salvataggio automatico non è stato completato. Resta nel parco o riprova.", "השמירה האוטומטית לא הושלמה. הישאר בפארק או נסה שוב." },
		[OpenTpwText.RetryCheckpoint] = new[] { "Retry", "Prøv igen", "Opnieuw proberen", "Réessayer", "Erneut versuchen", "다시 시도", "Ponów", "Reintentar", "Försök igen", "Riprova", "נסה שוב" },
		[OpenTpwText.CamcorderArmed] = new[] {
			"Click the ground to walk. C or Escape returns to the park view.",
			"Klik på jorden for at gå. C eller Escape vender tilbage til parkvisningen.",
			"Klik op de grond om te lopen. C of Escape keert terug naar het parkbeeld.",
			"Cliquez sur le sol pour marcher. C ou Échap revient à la vue du parc.",
			"Zum Gehen auf den Boden klicken. C oder Escape kehrt zur Parkansicht zurück.",
			"바닥을 클릭하면 걸어갑니다. C 또는 Esc를 누르면 공원 화면으로 돌아갑니다.",
			"Kliknij ziemię, aby iść. C lub Esc wraca do widoku parku.",
			"Haz clic en el suelo para andar. C o Esc vuelve a la vista del parque.",
			"Klicka på marken för att gå. C eller Escape återgår till parkvyn.", "Fai clic sul terreno per camminare. C o Esc torna alla vista del parco.", "לחץ על הקרקע כדי ללכת. C או Esc מחזירים לתצוגת הפארק." },
		[OpenTpwText.InvalidPrice] = new[] {
			"Enter a whole price from 0 to 2147483647.", "Indtast en hel pris fra 0 til 2147483647.",
			"Voer een gehele prijs van 0 tot 2147483647 in.", "Saisissez un prix entier de 0 à 2147483647.",
			"Einen ganzzahligen Preis von 0 bis 2147483647 eingeben.", "0에서 2147483647 사이의 정수 가격을 입력하십시오.", "Wpisz całkowitą cenę od 0 do 2147483647.", "Escribe un precio entero de 0 a 2147483647.", "Ange ett helt pris från 0 till 2147483647.", "Inserisci un prezzo intero da 0 a 2147483647.", "הזן מחיר שלם, לפחות 0 ולכל היותר 2147483647." },
		[OpenTpwText.NoSavedParks] = new[] { "No saved parks", "Ingen gemte parker", "Geen opgeslagen parken", "Aucun parc sauvegardé", "Keine gespeicherten Parks", "저장한 공원 없음", "Brak zapisanych parków", "No hay parques guardados", "Inga sparade parker", "Nessun parco salvato", "אין פארקים שמורים" },
		[OpenTpwText.RequiresMod] = new[] { "requires mod {0}", "kræver mod {0}", "vereist mod {0}", "nécessite le mod {0}", "benötigt Mod {0}", "모드 {0} 필요", "wymaga modyfikacji {0}", "requiere el mod {0}", "kräver mod {0}", "richiede la mod {0}", "דורש את ההרחבה {0}" },
		[OpenTpwText.CannotBuildHere] = new[] { "You can't build here", "Du kan ikke bygge her", "U kunt hier niet bouwen", "Impossible de construire ici", "Hier kann nicht gebaut werden", "여기에는 지을 수 없습니다", "Nie możesz tu budować", "No puedes construir aquí", "Du kan inte bygga här", "Non puoi costruire qui", "אי אפשר לבנות כאן" },
		// [EXT:coaster-closing-check] the reasons a coaster's circuit stays open: the closing link from the last pylon fails the validator, or a pylon is still marked invalid
		[OpenTpwText.CoasterCannotClose] = new[] { "The track can't be completed from the last pylon. Move that pylon or build another one first.", "Banen kan ikke gøres færdig fra den sidste pille. Flyt den pille, eller byg en til først.", "De baan kan vanaf de laatste pijler niet af. Verplaats die pijler of bouw er eerst nog een.", "La voie ne peut pas être terminée depuis le dernier pylône. Déplacez ce pylône ou construisez-en d'abord un autre.", "Die Strecke kann vom letzten Pfeiler aus nicht fertiggestellt werden. Versetze diesen Pfeiler oder baue zuerst einen weiteren.", "마지막 기둥에서는 트랙을 완성할 수 없습니다. 그 기둥을 옮기거나 먼저 기둥을 하나 더 세우세요.", "Toru nie można ukończyć od ostatniego filaru. Przesuń ten filar albo najpierw zbuduj kolejny.", "La vía no se puede terminar desde el último pilar. Mueve ese pilar o construye otro primero.", "Banan kan inte göras klar från den sista pelaren. Flytta pelaren eller bygg en till först.", "Il percorso non può essere completato dall'ultimo pilone. Sposta quel pilone o costruiscine prima un altro.", "אי אפשר להשלים את המסילה מהעמוד האחרון. הזיזו את העמוד או בנו קודם עוד עמוד." },
		[OpenTpwText.CoasterInvalidPylons] = new[] { "Move the pylons marked red before the track can be finished.", "Flyt de røde piller, før banen kan gøres færdig.", "Verplaats de rood gemarkeerde pijlers voordat de baan af kan.", "Déplacez les pylônes marqués en rouge avant de pouvoir terminer la voie.", "Versetze die rot markierten Pfeiler, bevor die Strecke fertig werden kann.", "트랙을 완성하려면 먼저 빨갛게 표시된 기둥을 옮기세요.", "Przesuń filary zaznaczone na czerwono, zanim tor będzie mógł zostać ukończony.", "Mueve los pilares marcados en rojo antes de poder terminar la vía.", "Flytta de rödmarkerade pelarna innan banan kan bli klar.", "Sposta i piloni segnati in rosso prima di poter completare il percorso.", "הזיזו את העמודים המסומנים באדום לפני שאפשר לסיים את המסילה." },
		[OpenTpwText.LobbyMenuHint] = new[] { "Esc: menu", "Esc: menuen", "Esc: menu openen", "Échap : menu", "Esc: Menü", "Esc: 메뉴", "Esc: wyświetl menu", "Esc: menú", "Esc: meny", "Esc: menù", "Esc: תפריט" },
		[OpenTpwText.AgeDays] = new[] { "{0} days", "{0} dage", "{0} dagen", "{0} jours", "{0} Tage", "{0}일", "{0} dni", "{0} días", "{0} dagar", "{0} giorni", "{0} ימים" },
		[OpenTpwText.NotSimulated] = new[] { "Not simulated yet", "Endnu ikke simuleret", "Nog niet gesimuleerd", "Pas encore simulé", "Noch nicht simuliert", "아직 시뮬레이션 안 됨", "Jeszcze nie symulowano", "Aún sin simular", "Inte simulerad ännu", "Non ancora simulato", "עדיין לא הודמה" },
		[OpenTpwText.Built] = new[] { "{0} built.", "{0} er bygget.", "{0} gebouwd.", "{0} construit.", "{0} gebaut.", "{0} 건설 완료.", "Zbudowano: {0}.", "{0} construido.", "{0} byggd.", "{0} costruito.", "{0} נבנה." },
		[OpenTpwText.LayQueue] = new[] { "Lay the queue from the entrance; press Back when done.", "Læg køen fra indgangen; tryk på Tilbage, når du er færdig.", "Leg de wachtrij vanaf de ingang; druk op Terug als je klaar bent.", "Posez la file depuis l'entrée ; appuyez sur Retour pour terminer.", "Lege die Warteschlange ab dem Eingang; drücke Zurück, wenn du fertig bist.", "입구에서 대기줄을 까십시오. 끝나면 뒤로를 누르십시오.", "Ułóż kolejkę od wejścia; po skończeniu naciśnij Powrót.", "Coloca la cola desde la entrada; pulsa Atrás al terminar.", "Lägg kön från ingången; tryck på Tillbaka när du är klar.", "Traccia la coda a partire dall'ingresso; premi Indietro quando hai finito.", "הנח את התור מהכניסה; לחץ חזרה בסיום." },
