		[OpenTpwText.BuyLandHint] = new[] { "Click two opposite corners of the land to buy; right click to cancel.", "Klik på to modsatte hjørner af grunden, du vil købe; højreklik for at annullere.", "Klik op twee tegenoverliggende hoeken van het land dat je wilt kopen; klik met rechts om te annuleren.", "Cliquez sur deux coins opposés du terrain à acheter ; clic droit pour annuler.", "Klicke auf zwei gegenüberliegende Ecken des Landes, das du kaufen willst; Rechtsklick bricht ab.", "구입할 부지의 대각 모서리 두 곳을 클릭하십시오. 오른쪽 클릭하면 취소됩니다.", "Kliknij dwa przeciwległe rogi gruntu do kupienia; PPM anuluje.", "Haz clic en dos esquinas opuestas del terreno que quieres comprar; clic derecho para cancelar.", "Klicka på två motsatta hörn av marken du vill köpa; högerklicka för att avbryta.", "Fai clic su due angoli opposti del terreno da acquistare; clic destro per annullare.", "לחץ על שתי פינות נגדיות של הקרקע שתרצה לקנות; לחיצה ימנית לביטול." },
		[OpenTpwText.CannotBuyLand] = new[] { "You cannot buy this land.", "Du kan ikke købe denne grund.", "Je kunt dit land niet kopen.", "Vous ne pouvez pas acheter ce terrain.", "Dieses Land kannst du nicht kaufen.", "이 부지는 구입할 수 없습니다.", "Nie możesz kupić tego gruntu.", "No puedes comprar este terreno.", "Du kan inte köpa den här marken.", "Non puoi acquistare questo terreno.", "אי אפשר לקנות את הקרקע הזאת." },
		// [EXT:pools-ui] the pool tool of the opentpw.pools extension
		[OpenTpwText.PoolRowPaint] = new[] { "Pool water", "Poolvand", "Zwembadwater", "Eau de piscine", "Poolwasser", "수영장 물", "Woda basenowa", "Agua de piscina", "Poolvatten", "Acqua della piscina", "מי בריכה" },
		[OpenTpwText.PoolRowErase] = new[] { "Remove pool water", "Fjern poolvand", "Zwembadwater verwijderen", "Retirer l'eau de piscine", "Poolwasser entfernen", "수영장 물 제거", "Usuń wodę basenową", "Quitar agua de piscina", "Ta bort poolvatten", "Rimuovi acqua della piscina", "הסר מי בריכה" },
		[OpenTpwText.PoolPaintHelp] = new[] { "Click and drag to paint pool water on level, empty land you own.", "Klik og træk for at male poolvand på jævn, tom grund, du ejer.", "Klik en sleep om zwembadwater te schilderen op vlak, leeg land dat je bezit.", "Cliquez et faites glisser pour peindre de l'eau de piscine sur un terrain plat, vide et à vous.", "Klicken und ziehen, um Poolwasser auf ebenes, leeres Land in deinem Besitz zu malen.", "클릭하고 끌어서 소유한 평평한 빈 땅에 수영장 물을 칠하십시오.", "Kliknij i przeciągnij, aby namalować wodę basenową na płaskim, pustym gruncie, który posiadasz.", "Haz clic y arrastra para pintar agua de piscina en terreno llano, vacío y tuyo.", "Klicka och dra för att måla poolvatten på jämn, tom mark som du äger.", "Fai clic e trascina per dipingere l'acqua della piscina su terreno piano, vuoto e di tua proprietà.", "לחץ וגרור כדי לצבוע מי בריכה על קרקע ישרה וריקה שבבעלותך." },
		[OpenTpwText.PoolEraseHelp] = new[] { "Click and drag to remove pool water; you get the money back.", "Klik og træk for at fjerne poolvand; du får pengene tilbage.", "Klik en sleep om zwembadwater te verwijderen; je krijgt het geld terug.", "Cliquez et faites glisser pour retirer l'eau de piscine ; l'argent vous est rendu.", "Klicken und ziehen, um Poolwasser zu entfernen; das Geld wird erstattet.", "클릭하고 끌어서 수영장 물을 제거하십시오. 돈이 환불됩니다.", "Kliknij i przeciągnij, aby usunąć wodę basenową; pieniądze wracają do ciebie.", "Haz clic y arrastra para quitar agua de piscina; te devuelven el dinero.", "Klicka och dra för att ta bort poolvatten; du får pengarna tillbaka.", "Fai clic e trascina per rimuovere l'acqua della piscina; il denaro ti viene restituito.", "לחץ וגרור כדי להסיר מי בריכה; הכסף מוחזר לך." },
		[OpenTpwText.PoolPaintHint] = new[] { "Pool water: press and drag over empty land to paint it; right click to stop.", "Poolvand: tryk og træk over tom grund for at male; højreklik for at stoppe.", "Zwembadwater: houd ingedrukt en sleep over leeg land om te schilderen; klik met rechts om te stoppen.", "Eau de piscine : appuyez et faites glisser sur un terrain vide pour peindre ; clic droit pour arrêter.", "Poolwasser: auf leerem Land drücken und ziehen, um zu malen; Rechtsklick beendet.", "수영장 물: 빈 땅 위에서 누른 채 끌어서 칠하십시오. 오른쪽 클릭하면 멈춥니다.", "Woda basenowa: naciśnij i przeciągnij po pustym gruncie, aby malować; PPM kończy.", "Agua de piscina: pulsa y arrastra sobre terreno vacío para pintar; clic derecho para parar.", "Poolvatten: tryck och dra över tom mark för att måla; högerklicka för att sluta.", "Acqua della piscina: premi e trascina sul terreno vuoto per dipingerla; clic destro per smettere.", "מי בריכה: לחץ וגרור על קרקע ריקה כדי לצבוע; לחיצה ימנית לסיום." },
		[OpenTpwText.PoolEraseHint] = new[] { "Remove pool water: press and drag over pool cells; right click to stop.", "Fjern poolvand: tryk og træk over poolfelter; højreklik for at stoppe.", "Zwembadwater verwijderen: houd ingedrukt en sleep over zwembadvakjes; klik met rechts om te stoppen.", "Retirer l'eau de piscine : appuyez et faites glisser sur les cases d'eau ; clic droit pour arrêter.", "Poolwasser entfernen: über Poolfelder drücken und ziehen; Rechtsklick beendet.", "수영장 물 제거: 수영장 칸 위에서 누른 채 끄십시오. 오른쪽 클릭하면 멈춥니다.", "Usuń wodę basenową: naciśnij i przeciągnij po polach basenu; PPM kończy.", "Quitar agua de piscina: pulsa y arrastra sobre las casillas de piscina; clic derecho para parar.", "Ta bort poolvatten: tryck och dra över poolrutor; högerklicka för att sluta.", "Rimuovi acqua della piscina: premi e trascina sulle caselle della piscina; clic destro per smettere.", "הסרת מי בריכה: לחץ וגרור על משבצות הבריכה; לחיצה ימנית לסיום." },
		[OpenTpwText.PoolTooSteep] = new[] { "The ground is too steep for a pool here", "Jorden er for skrå til en pool her", "De grond is hier te steil voor een zwembad", "Le terrain est trop pentu pour une piscine ici", "Der Boden ist hier zu steil für einen Pool", "이곳은 지면이 너무 가팔라 수영장을 만들 수 없습니다", "Teren jest tu zbyt stromy na basen", "El terreno es demasiado empinado para una piscina aquí", "Marken är för brant för en pool här", "Qui il terreno è troppo ripido per una piscina", "הקרקע כאן תלולה מדי לבריכה" },
		// [EXT:pools-swim] the swim session's guest states and the changing room's refusals
		[OpenTpwText.PoolStateSwimming] = new[] { "Swimming", "Svømmer", "Zwemt", "Nage", "Schwimmt", "수영 중", "Pływa", "Nadando", "Simmar", "Nuota", "שוחה" },
		[OpenTpwText.PoolStateClimbingOut] = new[] { "Climbing out of the pool", "Kravler op af poolen", "Klimt uit het zwembad", "Sort de la piscine", "Steigt aus dem Pool", "수영장에서 나오는 중", "Wychodzi z basenu", "Saliendo de la piscina", "Klättrar upp ur poolen", "Esce dalla piscina", "יוצא מהבריכה" },
		[OpenTpwText.PoolStateChanging] = new[] { "Changing", "Skifter tøj", "Kleedt zich om", "Se change", "Zieht sich um", "옷을 갈아입는 중", "Przebiera się", "Cambiándose", "Byter om", "Si cambia", "מחליף בגדים" },
		[OpenTpwText.PoolSwimmersInWater] = new[] { "Swimmers are in the water here", "Der er svømmere i vandet her", "Er zwemmers in het water hier", "Des nageurs sont dans l'eau ici", "Hier sind Schwimmer im Wasser", "이곳 물속에 수영하는 사람이 있습니다", "W wodzie są pływacy", "Hay nadadores en el agua aquí", "Det finns simmare i vattnet här", "Qui ci sono nuotatori in acqua", "יש כאן שחיינים במים" },
		[OpenTpwText.PoolChangingRoomNeedsWater] = new[] { "A changing room needs this pool water", "Et omklædningsrum har brug for dette poolvand", "Een kleedkamer heeft dit zwembadwater nodig", "Un vestiaire a besoin de cette eau de piscine", "Eine Umkleide braucht dieses Poolwasser", "탈의실에 이 수영장 물이 필요합니다", "Przebieralnia potrzebuje tej wody basenowej", "Un vestuario necesita esta agua de piscina", "Ett omklädningsrum behöver det här poolvattnet", "Uno spogliatoio ha bisogno di quest'acqua della piscina", "חדר הלבשה צריך את מי הבריכה האלה" },
		[OpenTpwText.PoolExtraNeedsEdge] = new[] { "A pool object needs a straight pool edge (a shower needs a changing room, a lounger or lamp needs water beside it)", "Et poolobjekt kræver en lige poolkant (et brusebad kræver et omklædningsrum, en liggestol eller lampe kræver vand ved siden af)", "Een zwembadobject heeft een rechte zwembadrand nodig (een douche een kleedkamer, een ligbed of lamp water ernaast)", "Un objet de piscine exige un bord droit (une douche un vestiaire, une chaise longue ou une lampe de l'eau à côté)", "Ein Poolobjekt braucht einen geraden Poolrand (eine Dusche eine Umkleide, eine Liege oder Lampe Wasser daneben)", "수영장 물건에는 곧은 수영장 가장자리가 필요합니다 (샤워기는 탈의실, 선베드와 조명은 옆에 물이 필요)", "Obiekt basenowy wymaga prostej krawędzi basenu (prysznic przebieralni, leżak lub lampa wody obok)", "Un objeto de piscina necesita un borde recto (una ducha un vestuario, una tumbona o lámpara agua al lado)", "Ett poolobjekt behöver en rak poolkant (en dusch ett omklädningsrum, en solstol eller lampa vatten bredvid)", "Un oggetto per piscina ha bisogno di un bordo dritto della piscina (una doccia ha bisogno di uno spogliatoio, un lettino o un lampione dell'acqua accanto)", "פריט בריכה צריך שפת בריכה ישרה: מקלחת צריכה חדר הלבשה, כיסא נוח או פנס צריכים מים לידם" },
		[OpenTpwText.PoolExtraNeedsWater] = new[] { "A pool object needs this pool water", "Et poolobjekt har brug for dette poolvand", "Een zwembadobject heeft dit zwembadwater nodig", "Un objet de piscine a besoin de cette eau de piscine", "Ein Poolobjekt braucht dieses Poolwasser", "수영장 물건에 이 수영장 물이 필요합니다", "Obiekt basenowy potrzebuje tej wody basenowej", "Un objeto de piscina necesita esta agua de piscina", "Ett poolobjekt behöver det här poolvattnet", "Un oggetto per piscina ha bisogno di quest'acqua della piscina", "פריט בריכה צריך את מי הבריכה האלה" },
		// [EXT:pools-slides] a splash cell with riders on it, or the foot of a tower's stairs with guests on them, cannot be erased
		[OpenTpwText.PoolSlideRiders] = new[] { "A slide has guests on it here", "En vandrutsjebane har gæster på sig her", "Er zijn gasten op een glijbaan hier", "Des clients sont sur un toboggan ici", "Hier sind Gäste auf einer Rutsche", "여기 물 미끄럼틀에 손님이 있습니다", "Na zjeżdżalni są tu goście", "Hay clientes en un tobogán aquí", "Det finns gäster på en rutschkana här", "Qui ci sono visitatori su uno scivolo", "יש כאן מבקרים על מגלשה" },
		// [EXT:pools-slides] the slide row, the tool's hints and the refusals of the slide tool
		[OpenTpwText.PoolRowSlide] = new[] { "Water slide track", "Vandrutsjebane", "Glijbaan aanleggen", "Piste de toboggan", "Wasserrutsche bauen", "물 미끄럼틀 트랙", "Tor zjeżdżalni", "Pista de tobogán", "Vattenrutschkana", "Pista dello scivolo d'acqua", "מסילת מגלשת מים" },
		[OpenTpwText.PoolSlideHint] = new[] { "Water slide: click or drag over the cells beside the tower; end over the pool. Backspace takes back a piece, right click stops.", "Vandrutsjebane: klik eller træk over felterne ved siden af tårnet; slut over poolen. Backspace tager et stykke tilbage, højreklik stopper.", "Glijbaan: klik of sleep over de vakjes naast de toren; eindig boven het zwembad. Backspace neemt een stuk terug, rechtsklik stopt.", "Toboggan : cliquez ou faites glisser sur les cases à côté de la tour ; terminez au-dessus de la piscine. Retour arrière reprend un élément, clic droit arrête.", "Wasserrutsche: Klicken oder ziehen Sie über die Felder neben dem Turm; enden Sie über dem Pool. Rücktaste nimmt ein Teil zurück, Rechtsklick beendet.", "물 미끄럼틀: 탑 옆 칸을 클릭하거나 끌어서 놓고 수영장 위에서 끝내세요. Backspace는 한 조각을 되돌리고 오른쪽 클릭은 멈춥니다.", "Zjeżdżalnia: kliknij lub przeciągnij po polach obok wieży; zakończ nad basenem. Backspace cofa element, prawy przycisk kończy.", "Tobogán: haz clic o arrastra por las casillas junto a la torre; termina sobre la piscina. Retroceso quita una pieza, clic derecho para.", "Vattenrutschkana: klicka eller dra över rutorna bredvid tornet; sluta över poolen. Backsteg tar tillbaka en bit, högerklick avslutar.", "Scivolo d'acqua: fai clic o trascina sulle caselle accanto alla torre; termina sopra la piscina. Backspace toglie un pezzo, il clic destro smette.", "מגלשת מים: לחץ או גרור על המשבצות שליד המגדל; סיים מעל הבריכה. Backspace מבטל חלק, לחיצה ימנית מסיימת." },
		[OpenTpwText.PoolSlideHelp] = new[] { "Click the cell beside the end of the slide to add a piece; a pool cell ends it with the splash.", "Klik på feltet ved enden af rutsjebanen for at tilføje et stykke; et poolfelt afslutter den med et plask.", "Klik op het vakje naast het eind van de glijbaan om een stuk toe te voegen; een zwembadvakje sluit af met de plons.", "Cliquez sur la case à côté de la fin du toboggan pour ajouter un élément ; une case de piscine le termine par l'éclaboussure.", "Klicken Sie auf das Feld neben dem Ende der Rutsche, um ein Teil anzufügen; ein Poolfeld beendet sie mit dem Platsch.", "미끄럼틀 끝 옆 칸을 클릭해 조각을 더하세요. 수영장 칸이 첨벙으로 끝맺습니다.", "Kliknij pole obok końca zjeżdżalni, aby dodać element; pole basenu kończy ją pluskiem.", "Haz clic en la casilla junto al final del tobogán para añadir una pieza; una casilla de piscina lo termina con el chapuzón.", "Klicka på rutan bredvid slutet av rutschkanan för att lägga till en bit; en poolruta avslutar den med plasket.", "Fai clic sulla casella accanto alla fine dello scivolo per aggiungere un pezzo; una casella della piscina lo termina con il tuffo.", "לחץ על המשבצת שליד קצה המגלשה כדי להוסיף חלק; משבצת בריכה מסיימת אותה בנחיתה במים." },
		[OpenTpwText.PoolSlideDone] = new[] { "The water slide is finished", "Vandrutsjebanen er færdig", "De glijbaan is klaar", "Le toboggan est terminé", "Die Wasserrutsche ist fertig", "물 미끄럼틀이 완성되었습니다", "Zjeżdżalnia jest gotowa", "El tobogán está terminado", "Vattenrutschkanan är färdig", "Lo scivolo d'acqua è finito", "מגלשת המים מוכנה" },
		[OpenTpwText.PoolSlideNoTower] = new[] { "Place a slide tower beside a pool first", "Placér først et rutsjebanetårn ved en pool", "Plaats eerst een glijbaantoren naast een zwembad", "Placez d'abord une tour de toboggan à côté d'une piscine", "Stellen Sie zuerst einen Rutschenturm neben einen Pool", "먼저 수영장 옆에 미끄럼틀 탑을 놓으세요", "Najpierw postaw wieżę zjeżdżalni obok basenu", "Primero coloca una torre de tobogán junto a una piscina", "Placera först ett rutschkanetorn bredvid en pool", "Prima metti una torre dello scivolo accanto a una piscina", "קודם הצב מגדל מגלשה ליד בריכה" },
		[OpenTpwText.PoolSlideTooSteep] = new[] { "The slide is too short for the tower's height: make it longer", "Rutsjebanen er for kort til tårnets højde: gør den længere", "De glijbaan is te kort voor de hoogte van de toren: maak hem langer", "Le toboggan est trop court pour la hauteur de la tour : allongez-le", "Die Rutsche ist für die Turmhöhe zu kurz: machen Sie sie länger", "미끄럼틀이 탑 높이에 비해 너무 짧습니다. 더 길게 만드세요", "Zjeżdżalnia jest za krótka jak na wysokość wieży: wydłuż ją", "El tobogán es demasiado corto para la altura de la torre: hazlo más largo", "Rutschkanan är för kort för tornets höjd: gör den längre", "Lo scivolo è troppo corto per l'altezza della torre: allungalo", "המגלשה קצרה מדי לגובה המגדל: האריך אותה" },
		[OpenTpwText.PoolSlideTooGentle] = new[] { "The slide is too long for the tower's height: shorten it", "Rutsjebanen er for lang til tårnets højde: gør den kortere", "De glijbaan is te lang voor de hoogte van de toren: maak hem korter", "Le toboggan est trop long pour la hauteur de la tour : raccourcissez-le", "Die Rutsche ist für die Turmhöhe zu lang: kürzen Sie sie", "미끄럼틀이 탑 높이에 비해 너무 깁니다. 더 짧게 만드세요", "Zjeżdżalnia jest za długa jak na wysokość wieży: skróć ją", "El tobogán es demasiado largo para la altura de la torre: acórtalo", "Rutschkanan är för lång för tornets höjd: korta den", "Lo scivolo è troppo lungo per l'altezza della torre: accorcialo", "המגלשה ארוכה מדי לגובה המגדל: קצר אותה" },
		[OpenTpwText.PoolSlideTooLow] = new[] { "The slide would touch the ground here", "Rutsjebanen ville røre jorden her", "De glijbaan zou hier de grond raken", "Le toboggan toucherait le sol ici", "Die Rutsche würde hier den Boden berühren", "미끄럼틀이 여기서 땅에 닿습니다", "Zjeżdżalnia dotknęłaby tu ziemi", "El tobogán tocaría el suelo aquí", "Rutschkanan skulle nudda marken här", "Qui lo scivolo toccherebbe il terreno", "כאן המגלשה תיגע בקרקע" },
		[OpenTpwText.PoolSlideNotNext] = new[] { "Continue the slide on a cell beside its end", "Fortsæt rutsjebanen på et felt ved siden af enden", "Ga verder op een vakje naast het eind van de glijbaan", "Continuez le toboggan sur une case à côté de son extrémité", "Setzen Sie die Rutsche auf einem Feld neben ihrem Ende fort", "미끄럼틀 끝 옆 칸에서 이어 가세요", "Kontynuuj zjeżdżalnię na polu obok jej końca", "Continúa el tobogán en una casilla junto a su final", "Fortsätt rutschkanan på en ruta bredvid slutet", "Continua lo scivolo su una casella accanto alla sua fine", "המשך את המגלשה במשבצת שליד הקצה שלה" },
		[OpenTpwText.PoolSlideNotPool] = new[] { "The slide must end over the tower's own pool", "Rutsjebanen skal ende over tårnets egen pool", "De glijbaan moet eindigen boven het zwembad van de toren", "Le toboggan doit finir au-dessus de la piscine de la tour", "Die Rutsche muss über dem Pool des Turms enden", "미끄럼틀은 탑과 이어진 수영장 위에서 끝나야 합니다", "Zjeżdżalnia musi kończyć się nad basenem wieży", "El tobogán debe terminar sobre la piscina de la torre", "Rutschkanan måste sluta över tornets egen pool", "Lo scivolo deve finire sopra la piscina della sua torre", "המגלשה חייבת להסתיים מעל הבריכה של המגדל שלה" },
		[OpenTpwText.PoolSlideBadStart] = new[] { "Start the slide on a cell beside the tower, not on the stairs' side", "Start rutsjebanen på et felt ved tårnet, ikke på trappesiden", "Begin de glijbaan op een vakje naast de toren, niet aan de kant van de trap", "Commencez le toboggan sur une case à côté de la tour, pas du côté de l'escalier", "Beginnen Sie die Rutsche auf einem Feld neben dem Turm, nicht auf der Treppenseite", "탑 옆 칸에서 시작하세요. 계단 쪽은 안 됩니다", "Zacznij zjeżdżalnię na polu obok wieży, nie od strony schodów", "Empieza el tobogán en una casilla junto a la torre, no del lado de las escaleras", "Börja rutschkanan på en ruta bredvid tornet, inte på trappsidan", "Inizia lo scivolo su una casella accanto alla torre, non dal lato delle scale", "התחל את המגלשה במשבצת שליד המגדל, לא בצד המדרגות" },
		[OpenTpwText.PoolSlideTowerNeedsPool] = new[] { "A slide tower must stand beside a pool", "Et rutsjebanetårn skal ligge ved siden af en pool", "Een glijbaantoren moet naast een zwembad staan", "Une tour de toboggan doit se trouver à côté d'une piscine", "Ein Rutschenturm muss neben einem Pool stehen", "미끄럼틀 탑은 수영장 옆에 있어야 합니다", "Wieża zjeżdżalni musi stać obok basenu", "Una torre de tobogán debe estar junto a una piscina", "Ett rutschkanetorn måste stå bredvid en pool", "Una torre dello scivolo deve stare accanto a una piscina", "מגדל מגלשה חייב לעמוד ליד בריכה" },
		[OpenTpwText.PoolSlideTowerFacesAway] = new[] { "Turn the slide tower: its stairs must face the pool", "Drej rutsjebanetårnet: trappen skal vende mod poolen", "Draai de glijbaantoren: de trap moet naar het zwembad kijken", "Tournez la tour de toboggan : son escalier doit faire face à la piscine", "Drehen Sie den Rutschenturm: Seine Treppe muss zum Pool zeigen", "탑을 돌리세요. 계단이 수영장을 향해야 합니다", "Obróć wieżę zjeżdżalni: schody muszą być zwrócone do basenu", "Gira la torre del tobogán: sus escaleras deben mirar a la piscina", "Vrid rutschkanetornet: trappan måste vetta mot poolen", "Ruota la torre dello scivolo: le scale devono essere rivolte verso la piscina", "סובב את מגדל המגלשה: המדרגות חייבות לפנות אל הבריכה" },
		[OpenTpwText.PoolSlideWaterNeeded] = new[] { "A slide needs this pool water", "En rutsjebane har brug for dette poolvand", "Een glijbaan heeft dit zwembadwater nodig", "Un toboggan a besoin de cette eau de piscine", "Eine Rutsche braucht dieses Poolwasser", "미끄럼틀에 이 수영장 물이 필요합니다", "Zjeżdżalnia potrzebuje tej wody basenowej", "Un tobogán necesita esta agua de piscina", "En rutschkana behöver det här poolvattnet", "Uno scivolo ha bisogno di quest'acqua della piscina", "מגלשה צריכה את מי הבריכה האלה" },
		[OpenTpwText.PoolChangingRoomNeedsPool] = new[] { "A changing room must stand beside a pool", "Et omklædningsrum skal ligge ved siden af en pool", "Een kleedkamer moet naast een zwembad staan", "Un vestiaire doit se trouver à côté d'une piscine", "Eine Umkleide muss neben einem Pool stehen", "탈의실은 수영장 옆에 있어야 합니다", "Przebieralnia musi stać obok basenu", "Un vestuario debe estar junto a una piscina", "Ett omklädningsrum måste ligga bredvid en pool", "Uno spogliatoio deve stare accanto a una piscina", "חדר הלבשה חייב לעמוד ליד בריכה" },
		// [EXT:pools-attractions] [EXT:pools-river] [EXT:pools-waves] the water attractions' refusals, the river option and the wave machine's settings
		[OpenTpwText.PoolAttractionNeedsPool] = new[] { "This must stand beside a pool", "Dette skal ligge ved siden af en pool", "Dit moet naast een zwembad staan", "Ceci doit se trouver à côté d'une piscine", "Das muss neben einem Pool stehen", "이것은 수영장 옆에 있어야 합니다", "To musi stać obok basenu", "Esto debe estar junto a una piscina", "Det här måste ligga bredvid en pool", "Deve stare accanto a una piscina", "זה חייב לעמוד ליד בריכה" },
		[OpenTpwText.PoolAttractionNeedsWater] = new[] { "This attraction needs this pool water", "Denne attraktion har brug for dette poolvand", "Deze attractie heeft dit zwembadwater nodig", "Cette attraction a besoin de cette eau de piscine", "Diese Attraktion braucht dieses Poolwasser", "이 어트랙션에는 이 수영장 물이 필요합니다", "Ta atrakcja potrzebuje tej wody basenowej", "Esta atracción necesita esta agua de piscina", "Den här attraktionen behöver detta poolvatten", "Questa attrazione ha bisogno di quest'acqua della piscina", "המתקן הזה צריך את מי הבריכה האלה" },
		// [EXT:pools-bridges] Build controls and placement feedback in every supported UI language.
		[OpenTpwText.PoolBridgeEast] = new[] { "Pool bridge (east-west)", "Poolbro (øst-vest)", "Zwembadbrug (oost-west)", "Pont de piscine (est-ouest)", "Poolbrücke (Ost-West)", "수영장 다리 (동서)", "Most nad basenem (wschód-zachód)", "Puente de piscina (este-oeste)", "Poolbro (öst-väst)", "Ponte sulla piscina (est-ovest)", "גשר בריכה (מזרח-מערב)" },
		[OpenTpwText.PoolBridgeSouth] = new[] { "Pool bridge (north-south)", "Poolbro (nord-syd)", "Zwembadbrug (noord-zuid)", "Pont de piscine (nord-sud)", "Poolbrücke (Nord-Süd)", "수영장 다리 (남북)", "Most nad basenem (północ-południe)", "Puente de piscina (norte-sur)", "Poolbro (nord-syd)", "Ponte sulla piscina (nord-sud)", "גשר בריכה (צפון-דרום)" },
		[OpenTpwText.PoolBridgeErase] = new[] { "Remove pool bridge", "Fjern poolbro", "Zwembadbrug verwijderen", "Retirer le pont de piscine", "Poolbrücke entfernen", "수영장 다리 제거", "Usuń most nad basenem", "Retirar puente de piscina", "Ta bort poolbro", "Rimuovi ponte sulla piscina", "הסר גשר בריכה" },
		[OpenTpwText.PoolBridgeHelp] = new[] { "Click the first land cell: 2 land, 3 water, 2 land; paths at both ends. Builds east or south. Use Remove pool bridge to undo. Right click or Escape leaves.", "Klik på første landfelt: 2 land, 3 vand, 2 land; stier i begge ender. Bygger mod øst eller syd. Brug Fjern poolbro for at fortryde. Højreklik eller Escape afslutter.", "Klik op het eerste landvak: 2 land, 3 water, 2 land; paden aan beide uiteinden. Bouwt naar het oosten of zuiden. Gebruik Zwembadbrug verwijderen om ongedaan te maken. Rechtsklik of Escape sluit af.", "Cliquez sur la première case de terre : 2 terre, 3 eau, 2 terre ; chemins aux deux extrémités. Construction vers l'est ou le sud. Retirez le pont pour annuler. Clic droit ou Échap pour quitter.", "Erstes Landfeld anklicken: 2 Land, 3 Wasser, 2 Land; Wege an beiden Enden. Bau nach Osten oder Süden. Zum Rückgängigmachen die Poolbrücke entfernen. Rechtsklick oder Escape beendet.", "첫 육지 칸을 클릭하세요: 육지 2칸, 물 3칸, 육지 2칸. 양 끝에 길이 필요합니다. 동쪽이나 남쪽으로 건설합니다. 취소하려면 다리를 제거하세요. 우클릭 또는 Escape로 종료합니다.", "Kliknij pierwsze pole lądu: 2 lądu, 3 wody, 2 lądu; ścieżki na obu końcach. Budowa na wschód lub południe. Aby cofnąć, usuń most. Prawy przycisk lub Escape kończy.", "Haz clic en la primera casilla de tierra: 2 de tierra, 3 de agua, 2 de tierra; caminos en ambos extremos. Construye hacia el este o el sur. Retira el puente para deshacer. Clic derecho o Escape para salir.", "Klicka på första landrutan: 2 land, 3 vatten, 2 land; gångvägar i båda ändar. Bygger österut eller söderut. Ta bort bron för att ångra. Högerklick eller Escape avslutar.", "Fai clic sulla prima casella di terra: 2 terra, 3 acqua, 2 terra; sentieri a entrambe le estremità. Costruisce verso est o sud. Rimuovi il ponte per annullare. Clic destro o Escape per uscire.", "לחץ על משבצת היבשה הראשונה: 2 יבשה, 3 מים, 2 יבשה; שבילים בשני הקצוות. הבנייה מזרחה או דרומה. הסר את הגשר כדי לבטל. לחיצה ימנית או Escape ליציאה." },
		[OpenTpwText.PoolBridgeEraseHelp] = new[] { "Click any bridge cell to remove it. Right click or Escape leaves.", "Klik på et brofelt for at fjerne broen. Højreklik eller Escape afslutter.", "Klik op een brugvak om de brug te verwijderen. Rechtsklik of Escape sluit af.", "Cliquez sur une case du pont pour le retirer. Clic droit ou Échap pour quitter.", "Ein Brückenfeld zum Entfernen anklicken. Rechtsklick oder Escape beendet.", "다리 칸을 클릭하여 제거하세요. 우클릭 또는 Escape로 종료합니다.", "Kliknij pole mostu, aby go usunąć. Prawy przycisk lub Escape kończy.", "Haz clic en una casilla del puente para retirarlo. Clic derecho o Escape para salir.", "Klicka på en broruta för att ta bort bron. Högerklick eller Escape avslutar.", "Fai clic su una casella del ponte per rimuoverlo. Clic destro o Escape per uscire.", "לחץ על משבצת בגשר כדי להסיר אותו. לחיצה ימנית או Escape ליציאה." },
		[OpenTpwText.PoolBridgeNeedsWater] = new[] { "A bridge needs a straight line of 2 land, 3 pool water, then 2 land cells, with paths at both ends.", "En bro kræver 2 landfelter, 3 poolvandfelter og 2 landfelter på en lige linje med stier i begge ender.", "Een brug vereist een rechte lijn van 2 landvakken, 3 zwembadwatervakken en 2 landvakken, met paden aan beide uiteinden.", "Un pont nécessite une ligne droite de 2 cases de terre, 3 d'eau de piscine puis 2 de terre, avec des chemins aux deux extrémités.", "Eine Brücke braucht eine gerade Reihe aus 2 Land-, 3 Poolwasser- und 2 Landfeldern mit Wegen an beiden Enden.", "다리는 일직선으로 육지 2칸, 수영장 물 3칸, 육지 2칸과 양 끝의 길이 필요합니다.", "Most wymaga prostej linii 2 pól lądu, 3 pól wody basenowej i 2 pól lądu oraz ścieżek na obu końcach.", "El puente necesita una línea recta de 2 casillas de tierra, 3 de agua de piscina y 2 de tierra, con caminos en ambos extremos.", "En bro kräver en rak rad med 2 landrutor, 3 poolvattenrutor och 2 landrutor, med gångvägar i båda ändar.", "Il ponte richiede una linea retta di 2 caselle di terra, 3 di acqua della piscina e 2 di terra, con sentieri a entrambe le estremità.", "גשר דורש קו ישר של 2 משבצות יבשה, 3 מי בריכה ואז 2 יבשה, עם שבילים בשני הקצוות." },
		[OpenTpwText.PoolBridgeNotBridge] = new[] { "There is no pool bridge here.", "Der er ingen poolbro her.", "Hier is geen zwembadbrug.", "Il n'y a pas de pont de piscine ici.", "Hier gibt es keine Poolbrücke.", "여기에 수영장 다리가 없습니다.", "Nie ma tu mostu nad basenem.", "Aquí no hay un puente de piscina.", "Det finns ingen poolbro här.", "Qui non c'è un ponte sulla piscina.", "אין כאן גשר בריכה." },
		[OpenTpwText.PoolBridgeStanding] = new[] { "Wait until everyone has left the bridge and its approaches.", "Vent, til alle har forladt broen og dens adgangsveje.", "Wacht tot iedereen de brug en de opritten heeft verlaten.", "Attendez que tout le monde ait quitté le pont et ses accès.", "Warten Sie, bis alle die Brücke und ihre Zugänge verlassen haben.", "모두 다리와 진입로를 벗어날 때까지 기다리세요.", "Poczekaj, aż wszyscy opuszczą most i dojścia do niego.", "Espera a que todos hayan salido del puente y sus accesos.", "Vänta tills alla har lämnat bron och dess tillfarter.", "Attendi che tutti abbiano lasciato il ponte e i suoi accessi.", "המתן עד שכולם יעזבו את הגשר ואת דרכי הגישה אליו." },
		[OpenTpwText.PoolBridgeTooSteep] = new[] { "The land under the bridge and its approaches must be flat.", "Jorden under broen og dens adgangsveje skal være flad.", "De grond onder de brug en de opritten moet vlak zijn.", "Le terrain sous le pont et ses accès doit être plat.", "Der Boden unter der Brücke und ihren Zugängen muss eben sein.", "다리와 진입로 아래의 지면은 평평해야 합니다.", "Teren pod mostem i dojściami musi być płaski.", "El terreno bajo el puente y sus accesos debe ser llano.", "Marken under bron och dess tillfarter måste vara plan.", "Il terreno sotto il ponte e i suoi accessi deve essere pianeggiante.", "הקרקע מתחת לגשר ולדרכי הגישה שלו חייבת להיות שטוחה." },
		[OpenTpwText.PoolBridgeEndNotPath] = new[] { "Both ends of the bridge must meet a path: lay a path on the red cell.", "Begge ender af broen skal møde en sti: læg en sti på det røde felt.", "Beide uiteinden van de brug moeten op een pad uitkomen: leg een pad op het rode vak.", "Les deux extrémités du pont doivent rejoindre un chemin : posez un chemin sur la case rouge.", "Beide Enden der Brücke müssen an einen Weg stoßen: Legen Sie einen Weg auf das rote Feld.", "다리의 양 끝은 길과 이어져야 합니다. 빨간 칸에 길을 까십시오.", "Oba końce mostu muszą łączyć się ze ścieżką: połóż ścieżkę na czerwonym polu.", "Los dos extremos del puente deben dar a un camino: pon un camino en la casilla roja.", "Brons båda ändar måste möta en gångväg: lägg en gångväg på den röda rutan.", "Entrambe le estremità del ponte devono raggiungere un sentiero: posa un sentiero sulla casella rossa.", "שני קצוות הגשר חייבים להגיע לשביל: הנח שביל על המשבצת האדומה." },
		[OpenTpwText.PoolBridgeLandIsWater] = new[] { "The red cell must be land: click the first land cell before the water, and the pool must be exactly 3 cells wide here.", "Det røde felt skal være land: klik på det første landfelt før vandet, og poolen skal være præcis 3 felter bred her.", "Het rode vak moet land zijn: klik op het eerste landvak vóór het water, en het zwembad moet hier precies 3 vakken breed zijn.", "La case rouge doit être de la terre : cliquez sur la première case de terre avant l'eau ; la piscine doit faire exactement 3 cases de large ici.", "Das rote Feld muss Land sein: Klicken Sie auf das erste Landfeld vor dem Wasser; der Pool muss hier genau 3 Felder breit sein.", "빨간 칸은 육지여야 합니다. 물 앞의 첫 육지 칸을 클릭하고, 이곳의 수영장 폭은 정확히 3칸이어야 합니다.", "Czerwone pole musi być lądem: kliknij pierwsze pole lądu przed wodą, a basen musi mieć tu dokładnie 3 pola szerokości.", "La casilla roja debe ser tierra: haz clic en la primera casilla de tierra antes del agua; la piscina debe tener aquí exactamente 3 casillas de ancho.", "Den röda rutan måste vara land: klicka på den första landrutan före vattnet, och poolen måste vara exakt 3 rutor bred här.", "La casella rossa deve essere terra: fai clic sulla prima casella di terra prima dell'acqua; qui la piscina deve essere larga esattamente 3 caselle.", "המשבצת האדומה חייבת להיות יבשה: לחץ על משבצת היבשה הראשונה לפני המים, והבריכה חייבת להיות כאן ברוחב 3 משבצות בדיוק." },
		[OpenTpwText.PoolBridgeBlocked] = new[] { "Something is in the way on the red cell: a ride, shop, scenery, slide, queue, track, fence post or protected ground.", "Noget står i vejen på det røde felt: en forlystelse, butik, dekoration, rutsjebane, kø, bane, hegnspæl eller beskyttet grund.", "Er staat iets in de weg op het rode vak: een attractie, winkel, decoratie, glijbaan, wachtrij, baan, hekpaal of beschermde grond.", "Quelque chose gêne sur la case rouge : une attraction, une boutique, un décor, un toboggan, une file d'attente, une voie, un poteau de clôture ou un terrain protégé.", "Auf dem roten Feld ist etwas im Weg: eine Attraktion, ein Laden, Dekoration, eine Rutsche, Warteschlange, Strecke, ein Zaunpfahl oder geschützter Boden.", "빨간 칸에 무언가가 있습니다. 놀이기구, 상점, 장식물, 미끄럼틀, 대기줄, 트랙, 울타리 기둥 또는 보호된 땅입니다.", "Na czerwonym polu coś przeszkadza: atrakcja, sklep, dekoracja, zjeżdżalnia, kolejka, tor, słupek ogrodzenia lub chroniony teren.", "Algo estorba en la casilla roja: una atracción, una tienda, decoración, un tobogán, una cola, una vía, un poste de valla o terreno protegido.", "Något står i vägen på den röda rutan: en attraktion, butik, dekoration, rutschkana, kö, bana, stängselstolpe eller skyddad mark.", "C'è qualcosa d'intralcio sulla casella rossa: un'attrazione, un negozio, una decorazione, uno scivolo, una coda, un binario, un palo di recinzione o un terreno protetto.", "משהו חוסם את המשבצת האדומה: מתקן, חנות, קישוט, מגלשה, תור, מסילה, עמוד גדר או קרקע מוגנת." },
		[OpenTpwText.PoolBridgeInTheWay] = new[] { "Another pool bridge is in the way on the red cell.", "En anden poolbro står i vejen på det røde felt.", "Er staat al een andere zwembadbrug op het rode vak.", "Un autre pont de piscine gêne sur la case rouge.", "Auf dem roten Feld ist eine andere Poolbrücke im Weg.", "빨간 칸에 다른 수영장 다리가 있습니다.", "Na czerwonym polu stoi już inny most nad basenem.", "Otro puente de piscina estorba en la casilla roja.", "En annan poolbro står i vägen på den röda rutan.", "Un altro ponte sulla piscina è d'intralcio sulla casella rossa.", "גשר בריכה אחר חוסם את המשבצת האדומה." },
		[OpenTpwText.PoolBridgeNotOwned] = new[] { "The park does not own the red cell's land yet.", "Parken ejer endnu ikke jorden under det røde felt.", "Het park bezit de grond van het rode vak nog niet.", "Le parc ne possède pas encore le terrain de la case rouge.", "Dem Park gehört der Boden des roten Feldes noch nicht.", "공원이 아직 빨간 칸의 땅을 소유하지 않았습니다.", "Park nie jest jeszcze właścicielem terenu czerwonego pola.", "El parque aún no es dueño del terreno de la casilla roja.", "Parken äger ännu inte marken under den röda rutan.", "Il parco non possiede ancora il terreno della casella rossa.", "הפארק עדיין אינו הבעלים של הקרקע במשבצת האדומה." },
		[OpenTpwText.PoolRowRiver] = new[] { "Lazy river water", "Doven flod", "Lazy river", "Rivière paresseuse", "Lazy River", "느린 강", "Leniwa rzeka", "Río lento", "Lat flod", "Acqua del fiume lento", "מי נהר עצל" },
		[OpenTpwText.PoolRiverHelp] = new[] { "Click and drag to paint a ring of river water; its current carries swimmers round.", "Klik og træk for at male en ring af flodvand; strømmen fører svømmerne rundt.", "Klik en sleep om een ring rivierwater te schilderen; de stroming voert zwemmers rond.", "Cliquez et faites glisser pour peindre un anneau de rivière ; le courant emporte les nageurs.", "Klicken und ziehen, um einen Ring aus Flusswasser zu malen; die Strömung trägt Schwimmer herum.", "클릭하고 끌어서 강물 고리를 칠하십시오. 물살이 수영객을 실어 나릅니다.", "Kliknij i przeciągnij, aby namalować pierścień wody rzecznej; nurt niesie pływaków.", "Haz clic y arrastra para pintar un anillo de río; la corriente lleva a los nadadores.", "Klicka och dra för att måla en ring av flodvatten; strömmen bär simmarna runt.", "Fai clic e trascina per dipingere un anello d'acqua di fiume; la corrente trasporta i nuotatori in giro.", "לחץ וגרור כדי לצבוע טבעת של מי נהר; הזרם שלו סוחף את השחיינים סביב." },
		[OpenTpwText.PoolRiverHint] = new[] { "Lazy river: press and drag to paint a ring one cell wide; right click to stop.", "Doven flod: tryk og træk for at male en ring, en celle bred; højreklik for at stoppe.", "Lazy river: houd ingedrukt en sleep om een ring van één vakje breed te schilderen; klik met rechts om te stoppen.", "Rivière paresseuse : appuyez et faites glisser pour peindre un anneau d'une case de large ; clic droit pour arrêter.", "Lazy River: drücken und ziehen, um einen Ring von einem Feld Breite zu malen; Rechtsklick beendet.", "느린 강: 누른 채 끌어서 한 칸 너비의 고리를 칠하십시오. 오른쪽 클릭하면 멈춥니다.", "Leniwa rzeka: naciśnij i przeciągnij, aby namalować pierścień szerokości jednego pola; PPM kończy.", "Río lento: pulsa y arrastra para pintar un anillo de una casilla de ancho; clic derecho para parar.", "Lat flod: tryck och dra för att måla en ring, en ruta bred; högerklicka för att sluta.", "Fiume lento: premi e trascina per dipingere un anello largo una casella; clic destro per smettere.", "נהר עצל: לחץ וגרור כדי לצבוע טבעת ברוחב משבצת אחת; לחיצה ימנית לסיום." },
