		[OpenTpwText.ModSafeMode] = new[] { "Safe mode: mods with scripts are off for this run", "Sikker tilstand: mods med scripts er slået fra", "Veilige modus: mods met scripts staan uit", "Mode sans échec : les mods avec scripts sont désactivés", "Abgesicherter Modus: Mods mit Skripten sind aus", "안전 모드: 스크립트 모드가 꺼져 있습니다", "Tryb awaryjny: modyfikacje ze skryptami są wyłączone", "Modo seguro: los mods con scripts están desactivados", "Säkert läge: mods med skript är avstängda", "Modalità sicura: le mod con script sono disattivate per questa sessione", "מצב בטוח: מודים עם תסריטים כבויים בהפעלה הזאת" },
