		[OpenTpwText.ModAffectsSimulation] = new[] { "Changes the park simulation", "Ændrer parksimuleringen", "Verandert de parksimulatie", "Modifie la simulation du parc", "Verändert die Parksimulation", "공원 시뮬레이션을 바꿉니다", "Zmienia symulację parku", "Cambia la simulación del parque", "Ändrar parksimuleringen", "Cambia la simulazione del parco", "משנה את הדמיית הפארק" },
		// [EXT:smarter-guests] the names and descriptions of the two guest extensions (docs/SMARTER-GUESTS.md)
		[OpenTpwText.ExtensionSmarterGuestsName] = new[] { "Smarter guests", "Klogere gæster", "Slimmere gasten", "Visiteurs plus malins", "Klügere Gäste", "더 똑똑한 손님", "Mądrzejsi goście", "Visitantes más listos", "Smartare gäster", "Visitatori più furbi", "מבקרים חכמים יותר" },
		[OpenTpwText.ExtensionSmarterGuestsDescription] = new[] { "Guests choose better: they weigh prices, spread over the rides, give up on far too long queues, plan for hunger and thirst, carry litter further to a bin and complain about litter and crowds. Changes the simulation: a park saved with it opens only with it, in the same version.", "Gæsterne vælger bedre: de vejer priser, fordeler sig over forlystelserne, opgiver alt for lange køer, planlægger efter sult og tørst, bærer affald længere til en skraldespand og klager over affald og trængsel. Ændrer simulationen: en park gemt med det åbner kun med det, i samme version.", "Gasten kiezen beter: ze wegen prijzen af, verdelen zich over de attracties, geven veel te lange rijen op, plannen voor honger en dorst, brengen afval verder naar een prullenbak en klagen over rommel en drukte. Verandert de simulatie: een park opgeslagen ermee opent alleen ermee, zelfde versie.", "Les visiteurs choisissent mieux : ils comparent les prix, se répartissent, quittent les files trop longues, anticipent faim et soif, portent leurs déchets plus loin à une poubelle et se plaignent des détritus et de la foule. Change la simulation : un parc enregistré avec ne s'ouvre qu'avec elle.", "Gäste wählen besser: Sie wägen Preise ab, verteilen sich auf die Fahrgeschäfte, verlassen viel zu lange Schlangen, planen Hunger und Durst ein, tragen Müll weiter zum Eimer und klagen über Müll und Gedränge. Ändert die Simulation: Ein damit gespeicherter Park öffnet nur damit, gleiche Version.", "손님이 더 좋은 선택을 합니다. 가격을 따지고, 놀이기구에 고르게 나뉘고, 너무 긴 줄은 포기하고, 배고픔과 목마름을 미리 챙기고, 더 먼 쓰레기통까지 쓰레기를 가져가고, 쓰레기와 혼잡에 불평합니다. 시뮬레이션이 바뀌므로 이 확장으로 저장한 공원은 같은 버전의 이 확장으로만 열립니다.", "Goście wybierają lepiej: porównują ceny, rozkładają się na atrakcje, rezygnują ze zbyt długich kolejek, planują głód i pragnienie, niosą śmieci dalej do kosza i narzekają na śmieci i tłok. Zmienia symulację: park zapisany z nim otworzy się tylko z nim, w tej samej wersji.", "Los visitantes eligen mejor: comparan precios, se reparten entre atracciones, dejan colas demasiado largas, prevén el hambre y la sed, llevan la basura más lejos a una papelera y se quejan de suciedad y gentío. Cambia la simulación: un parque guardado con ella solo se abre con ella, misma versión.", "Gäster väljer bättre: de väger priser, sprider sig över attraktionerna, ger upp alldeles för långa köer, planerar för hunger och törst, bär skräp längre till en papperskorg och klagar på skräp och trängsel. Ändrar simuleringen: en park sparad med den öppnas bara med den, i samma version.", "I visitatori scelgono meglio: valutano i prezzi, si spargono tra le attrazioni, lasciano code troppo lunghe, pensano a fame e sete, portano i rifiuti più lontano a un cestino e si lamentano di sporcizia e folla. Cambia la simulazione: un parco salvato con essa si apre solo con essa, stessa versione.", "המבקרים בוחרים טוב יותר: הם שוקלים מחירים, מתפזרים בין המתקנים, מוותרים על תורים ארוכים מדי, מתכננים מראש לרעב ולצמא, נושאים לכלוך רחוק יותר לפח ומתלוננים על לכלוך ועל צפיפות. זה משנה את ההדמיה: פארק שנשמר איתה נפתח רק איתה, באותה גרסה." },
		[OpenTpwText.RefusalsTitle] = new[] { "Why guests said no", "Hvorfor gæster sagde nej", "Waarom gasten nee zeiden", "Pourquoi les visiteurs refusent", "Warum Gäste ablehnten", "손님이 거절한 이유", "Dlaczego goście odmówili", "Por qué los visitantes rechazaron", "Varför gäster sa nej", "Perché i visitatori hanno detto di no", "למה המבקרים סירבו" },
		[OpenTpwText.RefusalTooExpensive] = new[] { "Too expensive", "For dyrt", "Te duur", "Trop cher", "Zu teuer", "너무 비쌈", "Za drogo", "Demasiado caro", "För dyrt", "Troppo caro", "יקר מדי" },
		[OpenTpwText.RefusalQueueTooLong] = new[] { "Queue too long", "Køen er for lang", "Wachtrij te lang", "File trop longue", "Schlange zu lang", "줄이 너무 김", "Za długa kolejka", "Cola demasiado larga", "Kön är för lång", "Coda troppo lunga", "התור ארוך מדי" },
		[OpenTpwText.RefusalTooScary] = new[] { "Too scary", "For skræmmende", "Te eng", "Trop effrayant", "Zu beängstigend", "너무 무서움", "Zbyt straszne", "Demasiado aterrador", "För läskigt", "Troppo spaventoso", "מפחיד מדי" },
		[OpenTpwText.RefusalTooBoring] = new[] { "Too boring", "For kedeligt", "Te saai", "Trop ennuyeux", "Zu langweilig", "너무 지루함", "Zbyt nudne", "Demasiado aburrido", "För tråkigt", "Troppo noioso", "משעמם מדי" },
		[OpenTpwText.RefusalRideUnavailable] = new[] { "Ride broken or closed", "Forlystelse i stykker eller lukket", "Attractie kapot of gesloten", "Attraction en panne ou fermée", "Fahrgeschäft defekt oder geschlossen", "놀이기구 고장 또는 닫힘", "Atrakcja zepsuta lub zamknięta", "Atracción averiada o cerrada", "Åkattraktion trasig eller stängd", "Attrazione guasta o chiusa", "המתקן מקולקל או סגור" },
		[OpenTpwText.ExtensionGuestInsightsName] = new[] { "Guest insights", "Gæsteindsigt", "Gastinzichten", "Suivi des visiteurs", "Gäste-Einblicke", "손님 분석", "Informacje o gościach", "Información de visitantes", "Gästinsikter", "Opinioni dei visitatori", "תובנות על המבקרים" },
		[OpenTpwText.ExtensionGuestInsightsDescription] = new[] { "Counts why guests turn down rides and shops and shows the totals in the park information window. Display only: it never changes the simulation or your saves.", "Tæller hvorfor gæster afviser forlystelser og butikker og viser totalerne i parkinformationsvinduet. Kun visning: ændrer aldrig simuleringen eller dine gemte parker.", "Telt waarom gasten attracties en winkels afwijzen en toont de totalen in het parkinformatievenster. Alleen weergave: verandert nooit de simulatie of je opgeslagen parken.", "Compte pourquoi les visiteurs refusent attractions et boutiques et affiche les totaux dans la fenêtre d'information du parc. Affichage seul : ne modifie jamais la simulation ni vos sauvegardes.", "Zählt, warum Gäste Fahrgeschäfte und Läden ablehnen, und zeigt die Summen im Parkinformationsfenster. Nur Anzeige: ändert nie die Simulation oder deine Spielstände.", "손님이 놀이기구와 상점을 거절하는 이유를 세어 공원 정보 창에 합계를 보여 줍니다. 표시 전용이며 시뮬레이션과 저장 파일을 바꾸지 않습니다.", "Liczy, dlaczego goście odmawiają atrakcji i sklepów, i pokazuje sumy w oknie informacji o parku. Tylko wyświetlanie: nigdy nie zmienia symulacji ani zapisów.", "Cuenta por qué los visitantes rechazan atracciones y tiendas y muestra los totales en la ventana de información del parque. Solo visualización: nunca cambia la simulación ni tus partidas guardadas.", "Räknar varför gäster tackar nej till attraktioner och butiker och visar summorna i parkinformationsfönstret. Endast visning: ändrar aldrig simuleringen eller dina sparade parker.", "Conta perché i visitatori rifiutano attrazioni e negozi e mostra i totali nella finestra delle informazioni sul parco. Solo visualizzazione: non cambia mai la simulazione né i tuoi salvataggi.", "סופר למה המבקרים מסרבים למתקנים ולחנויות ומציג את הסיכומים בחלון המידע על הפארק. תצוגה בלבד: זה אף פעם לא משנה את ההדמיה או את השמירות שלך." },
		[OpenTpwText.ExtensionPoolGuestArtName] = new[] { "Pool guest art", "Pool-gæstegrafik", "Zwembadgasten-graphics", "Visiteurs de la piscine", "Poolgast-Grafik", "수영장 손님 그래픽", "Grafika gości basenu", "Arte de los visitantes de la piscina", "Poolgästgrafik", "Grafica dei visitatori in piscina", "ציור מבקרים בבריכה" },
		[OpenTpwText.ExtensionPoolGuestArtDescription] = new[] { "With the Pools extension on, guests on land are drawn with OpenTPW's own high-resolution kids in their clothes, and in swimwear in the water. Turn it off to see the original guests on land (swimmers keep their swimwear). Display only: it never changes the simulation or your saves.", "Når Pools-udvidelsen er slået til, tegnes gæster på land med OpenTPW's egne højopløselige børn i deres tøj, og i badetøj i vandet. Slå fra for at se de originale gæster på land (svømmerne beholder deres badetøj). Kun visning: ændrer aldrig simuleringen eller dine gemte parker.", "Met de uitbreiding Zwembaden aan worden gasten op het land getekend met OpenTPW's eigen kinderen in hoge resolutie in hun kleren, en in zwemkleding in het water. Zet uit om de originele gasten op het land te zien (zwemmers houden hun zwemkleding). Alleen weergave: verandert nooit de simulatie of je opgeslagen parken.", "Avec l'extension Piscines activée, les visiteurs à terre sont dessinés avec les enfants haute résolution d'OpenTPW en vêtements, et en maillot dans l'eau. Désactivez pour voir les visiteurs d'origine à terre (les nageurs gardent leur maillot). Affichage seul : ne modifie jamais la simulation ni vos sauvegardes.", "Bei aktivierter Pools-Erweiterung werden Gäste an Land mit OpenTPWs eigenen hochauflösenden Kindern in Kleidung gezeichnet, im Wasser in Badekleidung. Ausschalten zeigt die Originalgäste an Land (Schwimmer behalten ihre Badekleidung). Nur Anzeige: ändert nie die Simulation oder deine Spielstände.", "수영장 확장이 켜져 있으면 육지의 손님은 OpenTPW의 고해상도 어린이 옷차림으로, 물속에서는 수영복 차림으로 그려집니다. 끄면 육지에서 원래 손님이 보입니다(수영하는 손님은 수영복 유지). 표시 전용이며 시뮬레이션과 저장 파일을 바꾸지 않습니다.", "Gdy rozszerzenie Baseny jest włączone, goście na lądzie są rysowani własnymi dzieciakami OpenTPW w wysokiej rozdzielczości w ubraniach, a w wodzie w strojach kąpielowych. Wyłącz, aby zobaczyć oryginalnych gości na lądzie (pływacy zachowują stroje). Tylko wyświetlanie: nigdy nie zmienia symulacji ani zapisów.", "Con la extensión Piscinas activada, los visitantes en tierra se dibujan con los niños de alta resolución de OpenTPW con su ropa, y en bañador en el agua. Desactívala para ver los visitantes originales en tierra (los nadadores conservan el bañador). Solo visualización: nunca cambia la simulación ni tus partidas guardadas.", "Med tillägget Pooler på ritas gäster på land med OpenTPW:s egna högupplösta barn i sina kläder, och i badkläder i vattnet. Stäng av för att se originalgästerna på land (badare behåller badkläderna). Endast visning: ändrar aldrig simuleringen eller dina sparade parker.", "Con l'estensione Piscine attiva, i visitatori a terra sono disegnati con i bambini ad alta risoluzione di OpenTPW nei loro vestiti, e in costume da bagno in acqua. Disattivala per vedere i visitatori originali a terra (chi nuota resta in costume). Solo visualizzazione: non cambia mai la simulazione né i tuoi salvataggi.", "כשהרחבת הבריכות פועלת, המבקרים ביבשה מצוירים כילדים ברזולוציה גבוהה של OpenTPW בבגדיהם, ובבגדי ים במים. כבה אותה כדי לראות את המבקרים המקוריים ביבשה; השחיינים נשארים בבגדי ים. תצוגה בלבד: זה אף פעם לא משנה את ההדמיה או את השמירות שלך." },
		[OpenTpwText.ExtensionRainMoodName] = new[] { "Rain mood", "Regnstemning", "Regenstemming", "Humeur sous la pluie", "Regenlaune", "빗속 기분", "Nastrój w deszczu", "Humor bajo la lluvia", "Regnstämning", "Umore sotto la pioggia", "מצב רוח בגשם" },
		[OpenTpwText.ExtensionRainMoodDescription] = new[] { "Guests mind the weather: in rain, storm and snow their happiness, thirst and hunger change once per qualifying day, as in Theme Park Inc, and an open umbrella softens the loss. It changes the simulation, so your saves record it while it is on.", "Gæsterne bekymrer sig om vejret: i regn, storm og sne ændres deres glæde, tørst og sult én gang pr. gyldig dag, som i Theme Park Inc, og en åben paraply dæmper tabet. Ændrer simuleringen, så dine gemte parker husker det, mens det er slået til.", "Gasten letten op het weer: bij regen, storm en sneeuw veranderen hun geluk, dorst en honger één keer per geldige dag, zoals in Theme Park Inc, en een open paraplu verzacht het verlies. Verandert de simulatie, dus je opgeslagen parken onthouden het zolang het aan staat.", "Les visiteurs subissent la météo : sous la pluie, l'orage et la neige, leur bonheur, leur soif et leur faim changent une fois par jour concerné, comme dans Theme Park Inc, et un parapluie ouvert atténue la perte. Modifie la simulation : vos sauvegardes l'enregistrent tant qu'elle est activée.", "Die Gäste achten aufs Wetter: bei Regen, Sturm und Schnee ändern sich Zufriedenheit, Durst und Hunger einmal pro betroffenem Tag, wie in Theme Park Inc, und ein offener Regenschirm mildert den Verlust. Ändert die Simulation, deine Spielstände merken sich das, solange sie an ist.", "손님이 날씨를 신경 씁니다. 비, 폭풍, 눈이 오면 행복, 갈증, 배고픔이 Theme Park Inc처럼 해당하는 날마다 한 번씩 변하고, 펼친 우산은 손해를 줄여 줍니다. 시뮬레이션을 바꾸므로 켜져 있는 동안 저장 파일에 기록됩니다.", "Goście przejmują się pogodą: w deszczu, burzy i śniegu ich zadowolenie, pragnienie i głód zmieniają się raz na kwalifikujący się dzień, jak w Theme Park Inc, a otwarty parasol łagodzi stratę. Zmienia symulację, więc zapisy je pamiętają, dopóki jest włączone.", "Los visitantes notan el tiempo: con lluvia, tormenta y nieve su felicidad, sed y hambre cambian una vez por día que cuenta, como en Theme Park Inc, y un paraguas abierto suaviza la pérdida. Cambia la simulación, así que tus partidas guardadas la registran mientras está activada.", "Gästerna bryr sig om vädret: i regn, storm och snö ändras deras glädje, törst och hunger en gång per giltig dag, som i Theme Park Inc, och ett öppet paraply mildrar förlusten. Ändrar simuleringen, så dina sparade parker minns det medan det är på.", "I visitatori sentono il tempo: con pioggia, temporale e neve la loro felicità, sete e fame cambiano una volta per giorno valido, come in Theme Park Inc, e un ombrello aperto attenua la perdita. Cambia la simulazione, quindi i tuoi salvataggi la registrano finché è attiva.", "המבקרים מושפעים מהמזג אוויר: בגשם, בסערה ובשלג האושר, הצמא והרעב שלהם משתנים פעם אחת בכל יום מתאים, כמו ב-Theme Park Inc, ומטריה פתוחה מרככת את ההפסד. ההרחבה משנה את ההדמיה, ולכן השמירות שלך רושמות אותה כל עוד היא פועלת." },
		[OpenTpwText.ExtensionUmbrellasName] = new[] { "Umbrellas", "Paraplyer", "Paraplu's", "Parapluies", "Regenschirme", "우산", "Parasole", "Paraguas", "Paraplyer", "Ombrelli", "מטריות" },
		[OpenTpwText.ExtensionUmbrellasDescription] = new[] { "Adds a brolly shop to every theme. Guests who own an umbrella open it in rain, storms and snow and close it in fine weather, and a balloon is let go when an umbrella opens. Turn it off to play without umbrellas; a park only records the extension while it has a brolly shop or an umbrella.", "Tilføjer en paraplybutik til hvert tema. Gæster med en paraply åbner den i regn, uvejr og sne og lukker den i godt vejr, og en ballon slippes, når en paraply åbnes. Slå fra for at spille uden paraplyer; en park gemmer kun udvidelsen, mens den har en paraplybutik eller en paraply.", "Voegt een paraplu-winkel toe aan elk thema. Gasten met een paraplu openen die bij regen, storm en sneeuw en sluiten hem bij mooi weer, en een ballon gaat los als een paraplu opengaat. Zet uit om zonder paraplu's te spelen; een park bewaart de uitbreiding alleen zolang het een paraplu-winkel of een paraplu heeft.", "Ajoute une boutique de parapluies à chaque thème. Les visiteurs qui ont un parapluie l'ouvrent sous la pluie, l'orage et la neige et le ferment par beau temps, et un ballon est lâché quand un parapluie s'ouvre. Désactivez pour jouer sans parapluies ; un parc n'enregistre l'extension que s'il a une boutique de parapluies ou un parapluie.", "Fügt jedem Thema einen Schirmladen hinzu. Gäste mit Regenschirm öffnen ihn bei Regen, Sturm und Schnee und schließen ihn bei schönem Wetter, und ein Ballon wird losgelassen, wenn sich ein Schirm öffnet. Ausschalten, um ohne Regenschirme zu spielen; ein Park speichert die Erweiterung nur, solange er einen Schirmladen oder einen Schirm hat.", "모든 테마에 우산 가게를 추가합니다. 우산이 있는 손님은 비, 폭풍, 눈이 올 때 우산을 펴고 날씨가 좋으면 접으며, 우산이 펴질 때 풍선은 놓아 버립니다. 끄면 우산 없이 플레이합니다. 공원은 우산 가게나 우산이 있을 때만 이 확장을 저장합니다.", "Dodaje sklep z parasolami do każdego motywu. Goście z parasolem otwierają go w deszczu, burzy i śniegu, a zamykają przy ladnej pogodzie, a balon jest puszczany, gdy parasol się otwiera. Wyłącz, aby grac bez parasoli; park zapisuje rozszerzenie tylko wtedy, gdy ma sklep z parasolami lub parasol.", "Añade una tienda de paraguas a cada tema. Los visitantes con paraguas lo abren con lluvia, tormenta y nieve y lo cierran con buen tiempo, y un globo se suelta cuando se abre un paraguas. Desactívala para jugar sin paraguas; un parque solo registra la extensión mientras tenga una tienda de paraguas o un paraguas.", "Lägger till en paraplybutik i varje tema. Gäster med paraply öppnar det i regn, oväder och snö och stänger det i fint väder, och en ballong släpps när ett paraply öppnas. Stäng av för att spela utan paraplyer; en park sparar tillagget bara så länge den har en paraplybutik eller ett paraply.", "Aggiunge un negozio di ombrelli a ogni tema. I visitatori con un ombrello lo aprono con pioggia, temporale e neve e lo chiudono con il bel tempo, e un palloncino viene lasciato andare quando si apre un ombrello. Disattivala per giocare senza ombrelli; un parco registra l'estensione solo finché ha un negozio di ombrelli o un ombrello.", "מוסיף חנות מטריות לכל נושא. מבקרים עם מטרייה פותחים אותה בגשם, בסערה ובשלג וסוגרים אותה במזג אוויר טוב, ובלון משוחרר כשמטרייה נפתחת. כבה כדי לשחק בלי מטריות; פארק שומר את ההרחבה רק כל עוד יש בו חנות מטריות או מטרייה." },
		[OpenTpwText.ExtensionWinterName] = new[] { "Winter", "Vinter", "Winter", "Hiver", "Winter", "겨울", "Zima", "Invierno", "Vinter", "Inverno", "חורף" },
		[OpenTpwText.ExtensionWinterDescription] = new[] { "Adds a winter kiosk and a glühwein stall to every theme. The kiosk sells a hat or earmuffs and then mittens all year round, but guests want them most in winter and in snow; the stall serves a warm drink with no drunk effects that sells best in the cold. Turn it off to play without them; a park only records the extension while it has one of these shops or a guest with a warm item.", "Tilføjer en vinterkiosk og en gløgbod til hvert tema. Kiosken sælger en hue eller ørevarmere og derefter vanter hele året, men gæsterne efterspørger dem mest om vinteren og i sne; boden serverer en varm drik uden fuldskabseffekter, der sælger bedst i kulden. Slå fra for at spille uden dem; en park gemmer kun udvidelsen, mens den har en af disse butikker eller en gæst med en varm ting.", "Voegt een winterkiosk en een glühweinkraam toe aan elk thema. De kiosk verkoopt het hele jaar een muts of oorwarmers en daarna wanten, maar gasten willen ze het meest in de winter en bij sneeuw; de kraam schenkt een warme drank zonder dronkenschap die het best verkoopt in de kou. Zet uit om zonder te spelen; een park bewaart de uitbreiding alleen zolang het een van deze winkels of een gast met een warm kledingstuk heeft.", "Ajoute un kiosque d'hiver et un stand de vin chaud à chaque thème. Le kiosque vend toute l'année un bonnet ou des cache-oreilles, puis des moufles, mais les visiteurs en veulent surtout en hiver et par temps de neige ; le stand sert une boisson chaude sans effets d'ivresse qui se vend surtout par temps froid. Désactivez pour jouer sans eux ; un parc n'enregistre l'extension que s'il a l'une de ces boutiques ou un visiteur avec un vêtement chaud.", "Fügt jedem Thema einen Winterkiosk und einen Glühweinstand hinzu. Der Kiosk verkauft das ganze Jahr über eine Mütze oder Ohrenwärmer und danach Fäustlinge, die Gäste wollen sie aber am meisten im Winter und bei Schnee; der Stand schenkt ein warmes Getränk ohne Rauscheffekte aus, das sich bei Kälte am besten verkauft. Ausschalten, um ohne sie zu spielen; ein Park speichert die Erweiterung nur, solange er einen dieser Läden oder einen Gast mit warmem Kleidungsstück hat.", "모든 테마에 겨울 가게와 글뤼바인 가게를 추가합니다. 겨울 가게는 일 년 내내 모자나 귀마개를 먼저, 그다음 벙어리장갑을 파는데 손님들은 겨울과 눈 오는 날에 가장 많이 찾고, 글뤼바인 가게는 취하는 효과가 없는 따뜻한 음료를 파는데 추울 때 가장 잘 팔립니다. 끄면 이것들 없이 플레이합니다. 공원은 이 가게나 따뜻한 물건을 가진 손님이 있을 때만 이 확장을 저장합니다.", "Dodaje kiosk zimowy i stoisko z grzańcem do każdego motywu. Kiosk sprzedaje czapkę lub nauszniki, a potem rękawiczki, przez cały rok, ale goście najchętniej kupują je zimą i w śniegu; stoisko podaje ciepły napój bez efektów upojenia, który najlepiej sprzedaje się w zimnie. Wyłącz, aby grać bez nich; park zapisuje rozszerzenie tylko wtedy, gdy ma jeden z tych sklepów lub gościa z ciepłą rzeczą.", "Añade un quiosco de invierno y un puesto de vino caliente a cada tema. El quiosco vende todo el año un gorro o unas orejeras y después manoplas, pero los visitantes los quieren sobre todo en invierno y con nieve; el puesto sirve una bebida caliente sin efectos de embriaguez que se vende mejor con frío. Desactívala para jugar sin ellos; un parque solo registra la extensión mientras tenga una de estas tiendas o un visitante con una prenda de abrigo.", "Lägger till en vinterkiosk och ett glöggstånd i varje tema. Kiosken säljer en mössa eller öronvärmare och sedan vantar hela året, men gästerna vill ha dem mest på vintern och i snö; ståndet serverar en varm dryck utan berusningseffekter som säljer bäst i kylan. Stäng av för att spela utan dem; en park sparar tillägget bara så länge den har någon av dessa butiker eller en gäst med ett varmt plagg.", "Aggiunge un chiosco invernale e una bancarella di vin brulé a ogni tema. Il chiosco vende tutto l'anno un cappello o dei paraorecchie e poi i guanti, ma gli ospiti li vogliono soprattutto in inverno e con la neve; la bancarella serve una bevanda calda senza effetti di ubriachezza che si vende meglio con il freddo. Disattivala per giocare senza; un parco registra l'estensione solo finché ha uno di questi negozi o un visitatore con un capo caldo.", "מוסיף קיוסק חורף ודוכן יין חם לכל נושא. הקיוסק מוכר כל השנה כובע או מחממי אוזניים ואחר כך כפפות, אבל האורחים רוצים אותם בעיקר בחורף ובשלג; הדוכן מגיש משקה חם בלי אפקטים של שכרות שנמכר הכי טוב בקור. כבה כדי לשחק בלעדיהם; פארק שומר את ההרחבה רק כל עוד יש בו אחת מהחנויות האלה או מבקר עם פריט חם." },
		[OpenTpwText.ExtensionWinterWeatherName] = new[] { "Wintry Decembers", "Vinterlige decembre", "Winterse decembers", "Décembres hivernaux", "Winterliche Dezember", "겨울 같은 12월", "Zimowe grudnie", "Diciembres invernales", "Vintriga decembermånader", "Dicembri invernali", "דצמברים חורפיים" },
		[OpenTpwText.ExtensionWinterWeatherDescription] = new[] { "In the jungle and fantasy parks December's rain and thunderstorms become snow, so umbrellas and the rain mood see snow instead of rain or storms. It changes the weather of every park of those themes, so your saves record it while it is on.", "I jungle- og fantasiparkerne bliver decembers regn og tordenvejr til sne, så paraplyer og regnstemningen ser sne i stedet for regn eller storm. Det ændrer vejret i alle parker med de temaer, så dine gemte parker husker det, mens det er slået til.", "In de jungle- en fantasieparken worden de regen en onweersbuien van december sneeuw, dus paraplu's en de regenstemming zien sneeuw in plaats van regen of storm. Het verandert het weer van elk park met die thema's, dus je opgeslagen parken onthouden het zolang het aan staat.", "Dans les parcs de la jungle et de la fantaisie, la pluie et les orages de décembre deviennent de la neige, si bien que les parapluies et l'humeur sous la pluie voient de la neige au lieu de pluie ou d'orage. Cela change la météo de tous les parcs de ces thèmes : vos sauvegardes l'enregistrent tant que l'option est activée.", "In den Dschungel- und Fantasieparks werden Regen und Gewitter im Dezember zu Schnee, sodass Regenschirme und die Regenlaune Schnee statt Regen oder Sturm sehen. Das ändert das Wetter jedes Parks dieser Themen, deine Spielstände merken sich das, solange es an ist.", "정글과 판타지 공원에서는 12월의 비와 뇌우가 눈으로 바뀌어, 우산과 비 기분이 비나 폭풍 대신 눈을 인식합니다. 해당 테마의 모든 공원의 날씨가 바뀌므로 켜져 있는 동안 저장 파일에 기록됩니다.", "W parkach dżungli i fantazji grudniowy deszcz i burze zamieniają się w śnieg, więc parasole i nastrój deszczowy widzą śnieg zamiast deszczu lub burzy. Zmienia pogodę w każdym parku tych motywów, więc zapisy ją pamiętają, dopóki jest włączona.", "En los parques de la jungla y de fantasía la lluvia y las tormentas de diciembre se vuelven nieve, así que los paraguas y el humor con lluvia ven nieve en lugar de lluvia o tormenta. Cambia el tiempo de todos los parques de esos temas, así que tus partidas guardadas lo registran mientras está activada.", "I djungel- och fantasiparkerna blir decembers regn och åskväder snö, så paraplyer och regnhumöret ser snö i stället för regn eller oväder. Det ändrar vädret i alla parker med de teman, så dina sparade parker minns det medan det är på.", "Nei parchi della giungla e della fantasia la pioggia e i temporali di dicembre diventano neve, così gli ombrelli e l'umore con la pioggia vedono neve invece di pioggia o temporale. Cambia il tempo di ogni parco di quei temi, quindi i tuoi salvataggi la registrano finché è attiva.", "בפארקי הג'ונגל והפנטזיה הגשם וסופות הרעמים של דצמבר הופכים לשלג, ולכן מטריות ומצב הרוח בגשם רואים שלג במקום גשם או סערה. זה משנה את מזג האוויר בכל פארק של הנושאים האלה, ולכן השמירות שלך רושמות את זה כל עוד זה פועל." },
		[OpenTpwText.ExtensionWinterColdName] = new[] { "Cold mood", "Kuldestemning", "Koude stemming", "Humeur au froid", "Kältelaune", "추위 기분", "Nastrój w mrozie", "Humor con el frío", "Köldstämning", "Umore al freddo", "מצב רוח בקור" },
		[OpenTpwText.ExtensionWinterColdDescription] = new[] { "In snow guests lose 2 happiness once per qualifying day, and get 1 back for a hat or earmuffs, 1 for mittens and 1 for a recent glühwein, never ending above zero. With it on, snow no longer cheers guests up through the rain mood. It changes the simulation, so your saves record it while it is on.", "I sne mister gæsterne 2 glæde én gang pr. gyldig dag, og får 1 tilbage for en hue eller ørevarmere, 1 for vanter og 1 for en nylig glühwein, dog aldrig over nul. Når den er slået til, glæder sne ikke længere gæsterne via regnstemningen. Ændrer simuleringen, så dine gemte parker husker det, mens det er slået til.", "In sneeuw verliezen gasten 2 geluk per geldige dag, en krijgen 1 terug voor een muts of oorwarmers, 1 voor wanten en 1 voor een recente glühwein, nooit boven nul. Als het aan staat, vrolijkt sneeuw gasten niet meer op via de regenstemming. Verandert de simulatie, dus je opgeslagen parken onthouden het zolang het aan staat.", "Dans la neige, les visiteurs perdent 2 de bonheur une fois par jour concerné, et en regagnent 1 pour un bonnet ou des cache-oreilles, 1 pour des moufles et 1 pour un vin chaud récent, sans jamais dépasser zéro. Activée, la neige ne remonte plus le moral via l'humeur sous la pluie. Modifie la simulation : vos sauvegardes l'enregistrent tant qu'elle est activée.", "Im Schnee verlieren Gäste einmal pro betroffenem Tag 2 Zufriedenheit und bekommen 1 zurück für eine Mütze oder Ohrenschützer, 1 für Fäustlinge und 1 für einen frischen Glühwein, nie über null. Wenn aktiv, heitert Schnee Gäste über die Regenlaune nicht mehr auf. Ändert die Simulation, deine Spielstände merken sich das, solange sie an ist.", "눈이 오면 손님은 해당하는 날마다 한 번씩 행복을 2 잃고, 모자나 귀마개로 1, 장갑으로 1, 최근에 마신 글뤼바인으로 1을 되찾으며 0을 넘지 않습니다. 켜 두면 눈이 더 이상 빗속 기분을 통해 손님을 기쁘게 하지 않습니다. 시뮬레이션을 바꾸므로 켜져 있는 동안 저장 파일에 기록됩니다.", "W śniegu goście tracą 2 zadowolenia raz na kwalifikujący się dzień i odzyskują 1 za czapkę lub nauszniki, 1 za rękawiczki i 1 za niedawne grzane wino, nigdy powyżej zera. Gdy jest włączone, śnieg nie poprawia już humoru przez nastrój w deszczu. Zmienia symulację, więc zapisy je pamiętają, dopóki jest włączone.", "Con nieve los visitantes pierden 2 de felicidad una vez por día que cuenta, y recuperan 1 por un gorro u orejeras, 1 por manoplas y 1 por un vino caliente reciente, sin pasar nunca de cero. Si está activada, la nieve ya no alegra a los visitantes mediante el humor bajo la lluvia. Cambia la simulación, así que tus partidas guardadas la registran mientras está activada.", "I snö förlorar gästerna 2 glädje en gång per giltig dag och får tillbaka 1 för en mössa eller öronskydd, 1 för vantar och 1 för en nyligen drucken glögg, aldrig över noll. När det är på piggar snö inte längre upp gästerna via regnstämningen. Ändrar simuleringen, så dina sparade parker minns det medan det är på.", "Con la neve i visitatori perdono 2 di felicità una volta per giorno valido e ne riprendono 1 per un cappello o paraorecchie, 1 per i guanti e 1 per un vin brulé recente, senza mai superare zero. Se attiva, la neve non rallegra più i visitatori tramite l'umore sotto la pioggia. Cambia la simulazione, quindi i tuoi salvataggi la registrano finché è attiva.", "בשלג המבקרים מאבדים 2 אושר פעם אחת בכל יום מתאים, ומקבלים 1 בחזרה על כובע או מחממי אוזניים, 1 על כפפות ו-1 על יין חם שנשתה לאחרונה, אך אף פעם לא מעל אפס. כשההרחבה פועלת, שלג כבר לא משמח מבקרים דרך מצב הרוח בגשם. ההרחבה משנה את ההדמיה, ולכן השמירות שלך רושמות אותה כל עוד היא פועלת." },
		[OpenTpwText.ExtensionWinterAlwaysName] = new[] { "Always winter", "Altid vinter", "Altijd winter", "Toujours l'hiver", "Immer Winter", "언제나 겨울", "Zawsze zima", "Siempre invierno", "Alltid vinter", "Sempre inverno", "תמיד חורף" },
		[OpenTpwText.ExtensionWinterAlwaysDescription] = new[] { "Winter weather all year: every month rolls its weather like December, so in the jungle, fantasy and Halloween parks it snows most of the time and the snow settles; space keeps its own weather. The winter kiosk and the glühwein stall sell as in winter all year. Includes Wintry Decembers. It changes the simulation, so your saves record it while it is on.", "Vintervejr hele året: hver måned får sit vejr som december, så i jungle-, fantasi- og halloweenparkerne sner det det meste af tiden, og sneen lægger sig; rummet beholder sit eget vejr. Vinterkiosken og gløgboden sælger som om vinteren hele året. Omfatter vinterlige decembre. Ændrer simuleringen, så dine gemte parker husker det, mens det er slået til.", "Winterweer het hele jaar: elke maand krijgt zijn weer zoals december, dus in de jungle-, fantasie- en halloweenparken sneeuwt het het grootste deel van de tijd en blijft de sneeuw liggen; de ruimte houdt haar eigen weer. De winterkiosk en de glühweinkraam verkopen het hele jaar als in de winter. Omvat winterse decembers. Verandert de simulatie, dus je opgeslagen parken onthouden het zolang het aan staat.", "Un temps d'hiver toute l'année : chaque mois tire sa météo comme décembre, si bien que dans les parcs de la jungle, de la fantaisie et d'Halloween il neige la plupart du temps et la neige tient ; l'espace garde sa propre météo. Le kiosque d'hiver et le stand de vin chaud vendent toute l'année comme en hiver. Inclut les décembres hivernaux. Modifie la simulation : vos sauvegardes l'enregistrent tant qu'elle est activée.", "Winterwetter das ganze Jahr: Jeder Monat bekommt sein Wetter wie der Dezember, sodass es in den Dschungel-, Fantasie- und Halloweenparks meistens schneit und der Schnee liegen bleibt; der Weltraum behält sein eigenes Wetter. Der Winterkiosk und der Glühweinstand verkaufen das ganze Jahr wie im Winter. Schließt die winterlichen Dezember ein. Ändert die Simulation, deine Spielstände merken sich das, solange es an ist.", "일 년 내내 겨울 날씨: 매달 12월처럼 날씨가 정해져 정글, 판타지, 할로윈 공원에서는 대부분 눈이 내리고 눈이 쌓입니다. 우주는 원래 날씨를 유지합니다. 겨울 가게와 글뤼바인 가게는 일 년 내내 겨울처럼 팝니다. 겨울 같은 12월을 포함합니다. 시뮬레이션을 바꾸므로 켜져 있는 동안 저장 파일에 기록됩니다.", "Zimowa pogoda przez cały rok: każdy miesiąc dostaje pogodę jak grudzień, więc w parkach dżungli, fantazji i Halloween przez większość czasu pada śnieg, który się osadza; kosmos zachowuje własną pogodę. Kiosk zimowy i stoisko z grzańcem sprzedają przez cały rok jak zimą. Obejmuje zimowe grudnie. Zmienia symulację, więc zapisy ją pamiętają, dopóki jest włączona.", "Tiempo de invierno todo el año: cada mes tiene el tiempo de diciembre, así que en los parques de la jungla, de fantasía y de Halloween nieva casi siempre y la nieve cuaja; el espacio conserva su propio tiempo. El quiosco de invierno y el puesto de vino caliente venden todo el año como en invierno. Incluye los diciembres invernales. Cambia la simulación, así que tus partidas guardadas la registran mientras está activada.", "Vinterväder hela året: varje månad får sitt väder som december, så i djungel-, fantasi- och halloweenparkerna snöar det för det mesta och snön blir liggande; rymden behåller sitt eget väder. Vinterkiosken och glöggståndet säljer hela året som på vintern. Omfattar vintriga decembermånader. Ändrar simuleringen, så dina sparade parker minns det medan det är på.", "Tempo invernale tutto l'anno: ogni mese ha il tempo di dicembre, così nei parchi della giungla, della fantasia e di Halloween nevica quasi sempre e la neve si deposita; lo spazio mantiene il suo tempo. Il chiosco invernale e la bancarella di vin brulé vendono tutto l'anno come d'inverno. Include i dicembri invernali. Cambia la simulazione, quindi i tuoi salvataggi la registrano finché è attiva.", "מזג אוויר חורפי כל השנה: כל חודש מקבל את מזג האוויר של דצמבר, כך שבפארקי הג'ונגל, הפנטזיה וליל כל הקדושים יורד שלג רוב הזמן והשלג נערם; החלל שומר על מזג האוויר שלו. קיוסק החורף ודוכן היין החם מוכרים כל השנה כמו בחורף. כולל דצמברים חורפיים. זה משנה את ההדמיה, ולכן השמירות שלך רושמות את זה כל עוד זה פועל." },
		[OpenTpwText.ExtensionRestoredAdviceName] = new[] { "Restored advice", "Genoprettede råd", "Herstelde adviezen", "Conseils restaurés", "Wiederhergestellte Hinweise", "복원된 조언", "Przywrócone porady", "Consejos restaurados", "Återställda råd", "Consigli ripristinati", "עצות משוחזרות" },
		[OpenTpwText.ExtensionRestoredAdviceDescription] = new[] { "The advisor says lines the original game never plays: security gaps, long queues, blocked ride exits, riders stuck in broken rides, arriving buses, planes and boats, golden ticket news and more. Advice only: it never changes the simulation or your saves.", "Rådgiveren siger replikker, som det originale spil aldrig afspiller: huller i sikkerheden, lange køer, blokerede udgange, gæster fast i defekte forlystelser, ankomne busser, fly og både, nyt om guldbilletter og mere. Kun råd: ændrer aldrig simuleringen eller dine gemte parker.", "De adviseur zegt zinnen die het originele spel nooit afspeelt: gaten in de beveiliging, lange wachtrijen, geblokkeerde uitgangen, gasten vast in kapotte attracties, aankomende bussen, vliegtuigen en boten, nieuws over gouden tickets en meer. Alleen advies: verandert nooit de simulatie of je opgeslagen parken.", "Le conseiller dit des phrases que le jeu d'origine ne joue jamais : trous dans la sécurité, files trop longues, sorties bloquées, visiteurs coincés dans des attractions en panne, bus, avions et bateaux qui arrivent, nouvelles des billets d'or et plus. Conseils seuls : ne modifie jamais la simulation ni vos sauvegardes.", "Der Berater sagt Sätze, die das Originalspiel nie abspielt: Lücken in der Sicherheit, lange Schlangen, blockierte Ausgänge, Gäste in defekten Fahrgeschäften, ankommende Busse, Flugzeuge und Boote, Neuigkeiten zu goldenen Tickets und mehr. Nur Hinweise: ändert nie die Simulation oder deine Spielstände.", "원래 게임에서는 나오지 않던 조언자의 대사를 들려줍니다. 경비 사각지대, 긴 줄, 막힌 출구, 고장 난 놀이기구에 갇힌 손님, 도착한 버스와 비행기와 배, 황금 티켓 소식 등. 조언만 하며 시뮬레이션과 저장 파일을 바꾸지 않습니다.", "Doradca mówi kwestie, których oryginalna gra nigdy nie odtwarza: luki w ochronie, długie kolejki, zablokowane wyjścia, goście uwięzieni w zepsutych atrakcjach, przyjeżdżające autobusy, samoloty i łodzie, wieści o złotych biletach i więcej. Tylko porady: nigdy nie zmienia symulacji ani zapisów.", "El asesor dice frases que el juego original nunca reproduce: huecos en la seguridad, colas largas, salidas bloqueadas, visitantes atrapados en atracciones averiadas, autobuses, aviones y barcos que llegan, noticias de billetes dorados y más. Solo consejos: nunca cambia la simulación ni tus partidas guardadas.", "Rådgivaren säger repliker som originalspelet aldrig spelar upp: luckor i säkerheten, långa köer, blockerade utgångar, gäster som sitter fast i trasiga attraktioner, ankommande bussar, flygplan och båtar, nyheter om guldbiljetter och mer. Endast råd: ändrar aldrig simuleringen eller dina sparade parker.", "Il consigliere dice frasi che il gioco originale non pronuncia mai: falle nella sicurezza, code lunghe, uscite delle attrazioni bloccate, passeggeri bloccati in attrazioni guaste, arrivi di autobus, aerei e barche, notizie sui biglietti d'oro e altro. Solo consigli: non cambia mai la simulazione né i tuoi salvataggi.", "היועץ אומר משפטים שהמשחק המקורי אף פעם לא משמיע: פרצות אבטחה, תורים ארוכים, יציאות חסומות של מתקנים, רוכבים שנתקעו במתקנים מקולקלים, אוטובוסים, מטוסים וסירות שמגיעים, חדשות על כרטיסי זהב ועוד. עצות בלבד: זה אף פעם לא משנה את ההדמיה או את השמירות שלך." },
