		[OpenTpwText.ModInputBrowserChoosing] = new[] { "Choose your own game folder in the browser's dialog; its files are copied into this page...", "Vælg din egen spilmappe i browserens dialog; filerne kopieres ind i denne side...", "Kies je eigen spelmap in het dialoogvenster van de browser; de bestanden worden naar deze pagina gekopieerd...", "Choisissez votre propre dossier de jeu dans la boîte de dialogue du navigateur ; ses fichiers sont copiés dans cette page...", "Wählen Sie Ihren eigenen Spielordner im Dialog des Browsers; seine Dateien werden in diese Seite kopiert...", "브라우저 대화 상자에서 자신의 게임 폴더를 선택하세요. 파일이 이 페이지로 복사됩니다...", "Wybierz własny folder gry w oknie dialogowym przeglądarki; jego pliki zostaną skopiowane do tej strony...", "Elige tu propia carpeta del juego en el cuadro de diálogo del navegador; sus archivos se copian en esta página...", "Välj din egen spelmapp i webbläsarens dialogruta; filerna kopieras in i den här sidan...", "Scegli la tua cartella del gioco nella finestra del browser; i suoi file vengono copiati in questa pagina...", "בחר את תיקיית המשחק שלך בחלון של הדפדפן; הקבצים שלה מועתקים לדף הזה..." },
		[OpenTpwText.ModInputBrowserLocked] = new[] { "A mod of this visit already uses these files. Reload the page to choose another folder.", "Et mod i dette besøg bruger allerede disse filer. Genindlæs siden for at vælge en anden mappe.", "Een mod van dit bezoek gebruikt deze bestanden al. Laad de pagina opnieuw om een andere map te kiezen.", "Un mod de cette visite utilise déjà ces fichiers. Rechargez la page pour choisir un autre dossier.", "Eine Mod dieses Besuchs verwendet diese Dateien bereits. Laden Sie die Seite neu, um einen anderen Ordner zu wählen.", "이번 방문의 모드가 이미 이 파일을 사용하고 있습니다. 다른 폴더를 선택하려면 페이지를 새로 고치세요.", "Mod z tej wizyty już używa tych plików. Odśwież stronę, aby wybrać inny folder.", "Un mod de esta visita ya usa estos archivos. Recarga la página para elegir otra carpeta.", "Ett mod under det här besöket använder redan filerna. Ladda om sidan för att välja en annan mapp.", "Una mod di questa visita usa già questi file. Ricarica la pagina per scegliere un'altra cartella.", "מוד של הביקור הזה כבר משתמש בקבצים האלה. טען מחדש את הדף כדי לבחור תיקייה אחרת." },
		[OpenTpwText.ModInputBrowserNone] = new[] { "The browser cannot take this folder; only Theme Park Inc data can be chosen here.", "Browseren kan ikke bruge denne mappe; kun Theme Park Inc-data kan vælges her.", "De browser kan deze map niet gebruiken; hier kan alleen Theme Park Inc-data worden gekozen.", "Le navigateur ne peut pas utiliser ce dossier ; seules les données de Theme Park Inc peuvent être choisies ici.", "Der Browser kann diesen Ordner nicht verwenden; hier können nur Theme Park Inc-Daten gewählt werden.", "브라우저가 이 폴더를 사용할 수 없습니다. 여기서는 Theme Park Inc 데이터만 선택할 수 있습니다.", "Przeglądarka nie może użyć tego folderu; tutaj można wybrać tylko dane Theme Park Inc.", "El navegador no puede usar esta carpeta; aquí solo se pueden elegir datos de Theme Park Inc.", "Webbläsaren kan inte använda den här mappen; här kan bara Theme Park Inc-data väljas.", "Il browser non può usare questa cartella; qui si possono scegliere solo dati di Theme Park Inc.", "הדפדפן לא יכול לקבל את התיקייה הזאת; כאן אפשר לבחור רק נתונים של Theme\u00A0Park\u00A0Inc." },
		[OpenTpwText.ModsSaved] = new[] { "Extensions and mods saved\n\nRestart OpenTPW to use the new choices.", "Udvidelser og mods gemt\n\nGenstart OpenTPW for at bruge de nye valg.", "Extensies en mods opgeslagen\n\nStart OpenTPW opnieuw om de nieuwe keuzes te gebruiken.", "Extensions et mods enregistrés\n\nRedémarrez OpenTPW pour utiliser les nouveaux choix.", "Erweiterungen und Mods gespeichert\n\nStarten Sie OpenTPW neu, um die neuen Einstellungen zu verwenden.", "확장과 모드를 저장했습니다\n\n새 선택을 쓰려면 OpenTPW를 다시 시작하십시오.", "Rozszerzenia i modyfikacje zapisane\n\nUruchom OpenTPW ponownie, aby użyć nowych ustawień.", "Extensiones y mods guardados\n\nReinicia OpenTPW para usar las nuevas opciones.", "Tillägg och mods sparade\n\nStarta om OpenTPW för att använda de nya valen.", "Estensioni e mod salvate\n\nRiavvia OpenTPW per usare le nuove scelte.", "ההרחבות והמודים נשמרו\n\nהפעל מחדש את OpenTPW כדי להשתמש בבחירות החדשות." },
