		[OpenTpwText.TpiCancelHelp] = new[] { "Put away the build item, remove tool, path and queue tools", "Læg byggeobjektet, fjernværktøjet samt sti- og kø-værktøjerne væk", "Berg het bouwobject, de verwijdertool en de pad- en wachtrijtools op", "Ranger l'objet à construire et les outils de retrait, de chemin et de file", "Bauobjekt sowie Entfernen-, Weg- und Warteschlangen-Werkzeug weglegen", "건설 항목과 제거, 길, 대기줄 도구를 치웁니다", "Schowaj budowany obiekt oraz narzędzia usuwania, ścieżek i kolejek", "Guardar el objeto a construir y las herramientas de quitar, camino y cola", "Lägg undan byggobjektet samt verktygen för borttagning, stigar och köer", "Metti via l'oggetto da costruire e gli strumenti di rimozione, sentiero e coda", "החזר את פריט הבנייה ואת כלי ההסרה, השביל והתור" },
		[OpenTpwText.TpiSpeedHelp] = new[] { "Simulation speed: paused, normal, fast, fastest", "Simuleringshastighed: sat på pause, normal, hurtig, hurtigst", "Simulatiesnelheid: gepauzeerd, normaal, snel, snelst", "Vitesse de simulation : pause, normale, rapide, très rapide", "Simulationsgeschwindigkeit: Pause, normal, schnell, am schnellsten", "시뮬레이션 속도: 일시정지, 보통, 빠름, 가장 빠름", "Szybkość symulacji: pauza, normalna, szybka, najszybsza", "Velocidad de simulación: pausa, normal, rápida, la más rápida", "Simuleringshastighet: pausad, normal, snabb, snabbast", "Velocità della simulazione: in pausa, normale, veloce, velocissima", "מהירות ההדמיה: מושהה, רגילה, מהירה, הכי מהירה" },
