		[OpenTpwText.TpiMenuHeading] = new[] { "Theme Park Inc experimental slice", "Theme Park Inc eksperimentelt udsnit", "Theme Park Inc experimenteel deel", "Tranche expérimentale de Theme Park Inc", "Experimenteller Theme-Park-Inc-Ausschnitt", "Theme Park Inc 실험적 일부", "Eksperymentalny fragment Theme Park Inc", "Fragmento experimental de Theme Park Inc", "Theme Park Inc experimentell del", "Parte sperimentale di Theme Park Inc", "חלק ניסיוני של Theme\u00A0Park\u00A0Inc" },
		[OpenTpwText.TpiLimits] = new[] { "experimental Theme Park Inc slice: money only (cash, loans, build and running costs, calendar); no staff, research, challenges, advisor, missions, Global Master Save, COS files, park saves or sharing, and no Theme Park Inc interface; none of it is checked against the original game", "eksperimentelt Theme Park Inc-udsnit: kun penge (kontanter, lån, bygge- og driftsomkostninger, kalender); ingen medarbejdere, forskning, udfordringer, rådgiver, missioner, Global Master Save, COS-filer, parkgemning eller deling, og ingen Theme Park Inc-brugerflade; intet af det er kontrolleret mod det originale spil", "experimenteel Theme Park Inc-deel: alleen geld (kas, leningen, bouw- en exploitatiekosten, kalender); geen personeel, onderzoek, uitdagingen, adviseur, missies, Global Master Save, COS-bestanden, parkopslag of delen, en geen Theme Park Inc-interface; niets hiervan is getoetst aan het originele spel", "tranche expérimentale de Theme Park Inc : argent seulement (trésorerie, prêts, coûts de construction et d'exploitation, calendrier) ; pas de personnel, de recherche, de défis, de conseiller, de missions, de Global Master Save, de fichiers COS, de sauvegardes ni de partage de parcs, et pas d'interface Theme Park Inc ; rien n'est vérifié par rapport au jeu d'origine", "experimenteller Theme-Park-Inc-Ausschnitt: nur das Geld (Kasse, Darlehen, Bau- und Betriebskosten, Kalender); kein Personal, keine Forschung, keine Herausforderungen, kein Berater, keine Missionen, kein Global Master Save, keine COS-Dateien, keine Park-Speicherstände und kein Teilen, und keine Theme-Park-Inc-Oberfläche; nichts davon wurde mit dem Originalspiel abgeglichen", "실험적 Theme Park Inc 일부: 돈만 작동합니다(현금, 대출, 건설·운영 비용, 달력). 직원, 연구, 도전 과제, 조언자, 임무, Global Master Save, COS 파일, 공원 저장과 공유가 없고 Theme Park Inc 인터페이스도 없습니다. 원작과 대조하지 않았습니다", "eksperymentalny fragment Theme Park Inc: tylko pieniądze (gotówka, pożyczki, koszty budowy i utrzymania, kalendarz); brak personelu, badań, wyzwań, doradcy, misji, Global Master Save, plików COS, zapisów parku i udostępniania oraz interfejsu Theme Park Inc; nic z tego nie jest sprawdzone z oryginalną grą", "fragmento experimental de Theme Park Inc: solo el dinero (efectivo, préstamos, costes de construcción y funcionamiento, calendario); sin personal, investigación, desafíos, asesor, misiones, Global Master Save, archivos COS, partidas guardadas del parque ni compartir, y sin interfaz de Theme Park Inc; nada se ha comprobado con el juego original", "experimentell Theme Park Inc-del: bara pengarna (kontanter, lån, bygg- och driftskostnader, kalender); ingen personal, forskning, utmaningar, rådgivare, uppdrag, Global Master Save, COS-filer, parksparning eller delning, och inget Theme Park Inc-gränssnitt; inget av det är kontrollerat mot originalspelet", "parte sperimentale di Theme Park Inc: solo il denaro (contanti, prestiti, costi di costruzione e di gestione, calendario); niente personale, ricerca, sfide, consigliere, missioni, Global Master Save, file COS, salvataggi o condivisione dei parchi, né interfaccia di Theme Park Inc; nulla di tutto ciò è verificato con il gioco originale", "חלק ניסיוני של Theme\u00A0Park\u00A0Inc: כסף בלבד - מזומן, הלוואות, עלויות בנייה ותפעול, לוח שנה; אין צוות, מחקר, אתגרים, יועץ, משימות, Global\u00A0Master\u00A0Save, קבצי COS, שמירות או שיתוף של פארקים, ואין ממשק של Theme\u00A0Park\u00A0Inc; שום דבר מזה לא נבדק מול המשחק המקורי" },
		[OpenTpwText.TpiResume] = new[] { "Resume", "Fortsæt", "Hervatten", "Reprendre", "Weiter", "계속", "Wznów", "Reanudar", "Fortsätt", "Riprendi", "המשך" },
		[OpenTpwText.TpiSaveLayout] = new[] { "Save layout checkpoint", "Gem layout", "Indeling opslaan", "Sauvegarder le plan", "Layout-Speicherpunkt anlegen", "배치 체크포인트 저장", "Zapisz punkt kontrolny układu", "Guardar punto de diseño", "Spara layout", "Salva il punto della disposizione", "שמור נקודת פריסה" },
		[OpenTpwText.TpiLayoutSaved] = new[] { "Layout saved. Loading it starts a new session; guests, script progress and clock are not saved.", "Layout gemt. Ved indlæsning startes en ny session; gæster, scriptforløb og ur gemmes ikke.", "Indeling opgeslagen. Bij het laden begint een nieuwe sessie; bezoekers, scriptvoortgang en klok worden niet opgeslagen.", "Plan sauvegardé. Le charger démarre une nouvelle session ; les visiteurs, la progression des scripts et l'horloge ne sont pas sauvegardés.", "Layout gespeichert. Beim Laden beginnt eine neue Sitzung; Besucher, Skriptfortschritt und Uhr werden nicht gespeichert.", "배치를 저장했습니다. 불러오면 새 세션이 시작되며 손님, 스크립트 진행, 시계는 저장되지 않습니다.", "Układ zapisany. Wczytanie go zaczyna nową sesję; goście, postęp skryptów i zegar nie są zapisywane.", "Diseño guardado. Al cargarlo empieza una sesión nueva; los visitantes, el progreso de los scripts y el reloj no se guardan.", "Layout sparad. Vid inläsning startas en ny session; gäster, skriptframsteg och klocka sparas inte.", "Disposizione salvata. Caricarla avvia una nuova sessione; visitatori, avanzamento degli script e orologio non vengono salvati.", "הפריסה נשמרה. טעינה שלה מתחילה הפעלה חדשה; מבקרים, התקדמות התסריטים והשעון לא נשמרים." },
		[OpenTpwText.TpiLoadLayout] = new[] { "Load layout - new session", "Indlæs layout - ny session", "Indeling laden - nieuwe sessie", "Charger le plan - nouvelle session", "Layout laden - neue Sitzung", "배치 불러오기 - 새 세션", "Wczytaj układ - nowa sesja", "Cargar diseño - sesión nueva", "Läs in layout - ny session", "Carica disposizione - nuova sessione", "טען פריסה - הפעלה חדשה" },
		[OpenTpwText.TpiQuit] = new[] { "Quit", "Afslut", "Afsluiten", "Quitter", "Beenden", "종료", "Wyjdź", "Salir", "Avsluta", "Esci", "יציאה" },
		[OpenTpwText.TpiConfirmLoad] = new[] { "Replace this world with the saved layout and start a NEW experimental session? Guests, ride script progress, simulation clock and audio restart. This is not a continuation or original TPI save.", "Erstat denne verden med den gemte layout og start en NY eksperimentel session? Gæster, forlystelsesscripts, simuleringsur og lyd starter forfra. Dette er ikke en fortsættelse eller en original TPI-gemning.", "Deze wereld vervangen door de opgeslagen indeling en een NIEUWE experimentele sessie starten? Bezoekers, attractiescripts, simulatieklok en audio starten opnieuw. Dit is geen voortzetting en geen origineel TPI-opslagbestand.", "Remplacer ce monde par le plan sauvegardé et démarrer une NOUVELLE session expérimentale ? Les visiteurs, la progression des scripts d'attractions, l'horloge de simulation et le son redémarrent. Ce n'est ni une reprise ni une sauvegarde TPI d'origine.", "Diese Welt durch das gespeicherte Layout ersetzen und eine NEUE experimentelle Sitzung starten? Besucher, Skriptfortschritt der Attraktionen, Simulationsuhr und Ton starten neu. Das ist keine Fortsetzung und kein originaler TPI-Spielstand.", "이 월드를 저장한 배치로 바꾸고 새 실험 세션을 시작하겠습니까? 손님, 놀이기구 스크립트 진행, 시뮬레이션 시계, 소리가 다시 시작됩니다. 이어하기나 원본 TPI 저장이 아닙니다.", "Zastąpić ten świat zapisanym układem i zacząć NOWĄ sesję eksperymentalną? Goście, postęp skryptów atrakcji, zegar symulacji i dźwięk zaczną się od nowa. To nie jest kontynuacja ani oryginalny zapis TPI.", "¿Sustituir este mundo por el diseño guardado y empezar una sesión experimental NUEVA? Los visitantes, el progreso de los scripts de atracciones, el reloj de simulación y el audio se reinician. No es una continuación ni una partida original de TPI.", "Ersätta den här världen med den sparade layouten och starta en NY experimentell session? Gäster, attraktionsskript, simuleringsklocka och ljud startar om. Detta är ingen fortsättning och ingen original TPI-sparning.", "Sostituire questo mondo con la disposizione salvata e avviare una NUOVA sessione sperimentale? Visitatori, avanzamento degli script delle attrazioni, orologio della simulazione e audio ripartono. Non è una continuazione né un salvataggio originale di TPI.", "להחליף את העולם הזה בפריסה השמורה ולהתחיל הפעלה ניסיונית חדשה? המבקרים, התקדמות התסריטים של המתקנים, שעון ההדמיה והשמע יתחילו מחדש. זו לא המשכה ולא שמירה מקורית של TPI." },
		[OpenTpwText.TpiLoadNew] = new[] { "Load new session", "Indlæs ny session", "Nieuwe sessie laden", "Charger une nouvelle session", "Neue Sitzung laden", "새 세션 불러오기", "Wczytaj nową sesję", "Cargar sesión nueva", "Läs in ny session", "Carica nuova sessione", "טען הפעלה חדשה" },
