		[OpenTpwText.ContinueAutosavePark] = new[] { "Continue autosave", "Fortsæt autogemning", "Autosave hervatten", "Continuer l'autosauvegarde", "Autospeicherung fortsetzen", "자동 저장본 계속", "Kontynuuj z autozapisu", "Continuar autoguardado", "Fortsätt autosparning", "Continua il salvataggio automatico", "המשך מהשמירה האוטומטית" },
		[OpenTpwText.AutosaveOption] = new[] { "Autosave:", "Autogem:", "Auto-opslaan:", "Sauvegarde auto :", "Autospeichern:", "자동 저장:", "Autozapis:", "Autoguardado:", "Autosparning:", "Salvataggio automatico:", "שמירה אוטומטית:" },
		[OpenTpwText.AutosaveHelp] = new[] {
			"Saves the park to its own slot every 5 minutes of play. Your manual save is never touched.",
			"Gemmer parken i sin egen plads hver 5. spilminut. Din manuelle gemning berøres aldrig.",
			"Slaat het park elke 5 minuten spelen op in een eigen slot. Je handmatige opslag blijft onaangeroerd.",
			"Sauvegarde le parc dans son propre emplacement toutes les 5 minutes de jeu. Votre sauvegarde manuelle n'est jamais modifiée.",
			"Speichert den Park alle 5 Spielminuten in einem eigenen Platz. Dein manueller Spielstand bleibt unberührt.",
			"5분 플레이마다 공원을 별도 슬롯에 저장합니다. 직접 저장한 파일은 바뀌지 않습니다.",
			"Zapisuje park w osobnym miejscu co 5 minut gry. Twój ręczny zapis pozostaje nietknięty.",
			"Guarda el parque en su propia ranura cada 5 minutos de juego. Tu guardado manual nunca se toca.",
			"Sparar parken på en egen plats var 5:e spelminut. Din manuella sparning rörs aldrig.",
			"Salva il parco in uno spazio tutto suo ogni 5 minuti di gioco. Il tuo salvataggio manuale non viene mai toccato.",
			"שומר את הפארק במקום משלו כל 5 דקות משחק. השמירה הידנית שלך אף פעם לא משתנה." },
		// [EXT:evening] the evening and night extension (docs/EVENING.md)
		[OpenTpwText.ExtensionEveningName] = new[] { "Evening and night", "Aften og nat", "Avond en nacht", "Soir et nuit", "Abend und Nacht", "저녁과 밤", "Wieczór i noc", "Tarde y noche", "Kväll och natt", "Sera e notte", "ערב ולילה" },
		[OpenTpwText.ExtensionEveningDescription] = new[] {
			"A day and night cycle: the sun sets, sky, ground and water darken, and lamps and pool lights switch on at dusk. It follows play time and pauses with the game. Adds a torch to every theme; a park only records the extension while it has a torch.",
			"En dag- og natcyklus: solen går ned, himmel, jord og vand bliver mørkere, og lamper og poollys tændes i skumringen. Følger spilletiden og står stille ved pause. Tilføjer en fakkel til hvert tema; en park gemmer kun udvidelsen, mens den har en fakkel.",
			"Een dag- en nachtcyclus: de zon gaat onder, lucht, grond en water worden donkerder en lampen en zwembadlichten gaan aan in de schemering. Volgt de speeltijd en pauzeert met het spel. Voegt aan elk thema een fakkel toe; een park bewaart de uitbreiding alleen met een fakkel.",
			"Un cycle jour et nuit : le soleil se couche, ciel, sol et eau s'assombrissent, et lampes et lumières de piscine s'allument au crépuscule. Suit le temps de jeu et s'arrête en pause. Ajoute une torche à chaque thème ; un parc n'enregistre l'extension que s'il a une torche.",
			"Ein Tag-und-Nacht-Zyklus: Die Sonne geht unter, Himmel, Boden und Wasser werden dunkler, Lampen und Poollichter gehen in der Dämmerung an. Folgt der Spielzeit und pausiert mit dem Spiel. Fügt jedem Thema eine Fackel hinzu; ein Park speichert die Erweiterung nur mit einer Fackel.",
			"낮과 밤의 주기: 해가 지면 하늘과 땅, 물이 어두워지고 해질녘에 가로등과 수영장 조명이 켜집니다. 공원 속도가 아니라 플레이 시간을 따르며 일시 정지하면 멈춥니다. 모든 테마에 횃불을 추가합니다. 공원은 횃불이 있을 때만 이 확장을 저장합니다.",
			"Cykl dnia i nocy: słońce zachodzi, niebo, ziemia i woda ciemnieją, a lampy i światła basenów zapalają się o zmierzchu. Zależy od czasu gry i staje przy pauzie. Dodaje pochodnię do każdego motywu; park zapisuje rozszerzenie tylko wtedy, gdy ma pochodnię.",
			"Un ciclo de día y noche: el sol se pone, cielo, suelo y agua se oscurecen, y lámparas y luces de piscina se encienden al atardecer. Sigue el tiempo de juego y se detiene en pausa. Añade una antorcha a cada tema; un parque solo registra la extensión si tiene una antorcha.",
			"En dag- och nattcykel: solen går ner, himmel, mark och vatten blir mörkare, och lampor och poolbelysning tänds i skymningen. Följer speltiden och står still vid paus. Lägger till en fackla i varje tema; en park sparar tillägget bara så länge den har en fackla.",
			"Un ciclo di giorno e notte: il sole tramonta, cielo, terreno e acqua si scuriscono, e lampioni e luci delle piscine si accendono al crepuscolo. Segue il tempo di gioco e si ferma in pausa. Aggiunge una torcia a ogni tema; un parco registra l'estensione solo se ha una torcia.",
			"מחזור של יום ולילה: השמש שוקעת, השמיים, הקרקע והמים מחשיכים, ומנורות ואורות הבריכות נדלקים בשקיעה. עוקב אחרי זמן המשחק, לא אחרי מהירות הפארק, ונעצר בהשהיה. מוסיף לפיד לכל נושא; פארק שומר את ההרחבה רק כל עוד יש בו לפיד." },
		// [EXT:winter-snow] the settling snow extension (docs/WINTER.md)
		[OpenTpwText.ExtensionWinterSnowName] = new[] { "Settling snow", "Sne der lægger sig", "Blijvende sneeuw", "Neige qui se dépose", "Liegenbleibender Schnee", "쌓이는 눈", "Zalegający śnieg", "Nieve que cuaja", "Snö som lägger sig", "Neve che si posa", "שלג שנערם" },
		[OpenTpwText.ExtensionWinterSnowDescription] = new[] {
			"Snow settles on the ground, roofs and objects while it snows and melts afterwards; paths turn to slush. It follows the weather and pauses with the game. Only snowy weather shows it (the Halloween world). Display only.",
			"Sneen lægger sig på jorden, tagene og tingene, mens det sner, og smelter bagefter; stierne bliver til sjap. Følger vejret og står stille ved pause. Kun snevejr viser den (Halloween-verdenen). Kun visning.",
			"Sneeuw blijft liggen op de grond, daken en objecten terwijl het sneeuwt en smelt daarna weg; paden worden sneeuwmodder. Volgt het weer en pauzeert met het spel. Alleen bij sneeuw zichtbaar (de Halloween-wereld). Alleen weergave.",
			"La neige se dépose sur le sol, les toits et les objets pendant la chute, puis fond; les allées deviennent de la gadoue. Suit la météo et s'arrête en pause. Visible seulement par temps de neige (le monde Halloween). Affichage seulement.",
			"Schnee bleibt auf Boden, Dächern und Objekten liegen, solange es schneit, und schmilzt danach; Wege werden zu Matsch. Folgt dem Wetter und pausiert mit dem Spiel. Nur bei Schneewetter sichtbar (die Halloween-Welt). Nur Anzeige.",
			"눈이 오는 동안 땅, 지붕, 물체 위에 눈이 쌓이고 그친 뒤에는 녹으며 길은 진창이 됩니다. 날씨를 따르고 일시 정지하면 멈춥니다. 눈이 오는 날씨에서만 보입니다(할로윈 월드). 표시만 바꿉니다.",
			"Śnieg zalega na ziemi, dachach i obiektach, gdy pada, a potem topnieje; ścieżki zamieniają się w breję. Zależy od pogody i staje przy pauzie. Widać go tylko przy śnieżnej pogodzie (świat Halloween). Tylko wygląd.",
			"La nieve cuaja en el suelo, los tejados y los objetos mientras nieva y luego se derrite; los caminos se vuelven nieve derretida. Sigue el tiempo y se detiene en pausa. Solo se ve con tiempo de nieve (el mundo Halloween). Solo visual.",
			"Snön lägger sig på marken, taken och föremålen medan det snöar och smälter sedan bort; stigarna blir till snöslask. Följer vädret och står still vid paus. Syns bara vid snöväder (Halloween-världen). Bara visning.",
			"La neve si posa su terreno, tetti e oggetti mentre nevica e poi si scioglie; i sentieri diventano fanghiglia. Segue il meteo e si ferma in pausa. Si vede solo con tempo nevoso (il mondo Halloween). Solo aspetto.",
			"שלג מצטבר על הקרקע, הגגות והעצמים בזמן שיורד שלג ונמס אחר כך; השבילים הופכים לבוץ שלג. עוקב אחרי מזג האוויר ונעצר בהשהיה. נראה רק בשלג (עולם ליל המכשפות). תצוגה בלבד.",
		},
		[OpenTpwText.EveningOption] = new[] { "Day cycle:", "Dagscyklus:", "Dagcyclus:", "Cycle du jour :", "Tageszyklus:", "낮밤 주기:", "Cykl dnia:", "Ciclo del día:", "Dygnscykel:", "Ciclo del giorno:", "מחזור יום:" },
		[OpenTpwText.EveningHelp] = new[] {
			"How long a full day and night lasts in minutes of play, or a fixed look. Used only while the Evening and night extension is on (Extensions and mods).",
			"Hvor længe en hel dag og nat varer i spilminutter, eller et fast udseende. Bruges kun, mens udvidelsen Aften og nat er slået til (Udvidelser og mods).",
			"Hoe lang een hele dag en nacht duurt in speelminuten, of een vaste weergave. Wordt alleen gebruikt als de uitbreiding Avond en nacht aan staat (Uitbreidingen en mods).",
			"La durée d'un jour et d'une nuit complets en minutes de jeu, ou un aspect fixe. Utilisé seulement quand l'extension Soir et nuit est activée (Extensions et mods).",
			"Wie lange ein ganzer Tag und eine ganze Nacht dauern, in Spielminuten, oder ein fester Zustand. Wird nur verwendet, solange die Erweiterung Abend und Nacht an ist (Erweiterungen und Mods).",
			"하루와 밤 한 주기가 플레이 시간으로 몇 분인지, 또는 고정된 모습을 정합니다. 확장 기능 저녁과 밤이 켜져 있을 때만 쓰입니다(확장 기능 및 모드).",
			"Jak długo trwa pełny dzień i noc w minutach gry albo stały wygląd. Używane tylko przy włączonym rozszerzeniu Wieczór i noc (Rozszerzenia i mody).",
			"Cuánto dura un día y una noche completos en minutos de juego, o un aspecto fijo. Solo se usa mientras la extensión Tarde y noche está activada (Extensiones y mods).",
			"Hur länge en hel dag och natt varar i spelminuter, eller ett fast utseende. Används bara när tillägget Kväll och natt är på (Tillägg och mods).", "Quanto dura un giorno e una notte completi in minuti di gioco, oppure un aspetto fisso. Usato solo mentre l'estensione Sera e notte è attiva (Estensioni e mod).", "כמה זמן נמשכים יום ולילה שלמים בדקות משחק, או מראה קבוע. בשימוש רק כשההרחבה ערב ולילה מופעלת (הרחבות ומודים)." },
