	public static IReadOnlyList<string> SupportedLanguages => Languages;

	/// <summary>The label in <paramref name="language"/>; English for languages without a translation.</summary>
	public static string Get( OpenTpwText key, string language )
	{
		if ( ColumnOf.TryGetValue( language, out var other ) )
			language = other;
		var column = Array.FindIndex( Languages, name => string.Equals( name, language, StringComparison.OrdinalIgnoreCase ) );
		return table[key][Math.Max( 0, column )];
	}

	/// <summary>
	/// The name of <paramref name="language"/> to show in the language row: its own name ("한국어") when <paramref name="canDraw"/> says the
	/// current UI font draws every character of it, otherwise its English name ("Korean"), which every font draws. The row is shown
	/// in the language in use, so a Latin-only font would otherwise show Hangul as missing glyphs until the switch.
	/// </summary>
	public static string DisplayName( string language, Func<char, bool>? canDraw = null )
	{
		var own = LanguageNames.TryGetValue( language, out var name ) ? name : language;
		return canDraw == null || own.All( canDraw ) ? own : language;
	}

	/// <summary>Every text in <paramref name="language"/>, with the language names as the language row shows them (<see cref="DisplayName"/>).</summary>
	public static IEnumerable<string> AllTexts( string language, Func<char, bool>? canDraw = null ) =>
		Enum.GetValues<OpenTpwText>().Select( key => Get( key, language ) ).Concat( LanguageNames.Keys.Select( name => DisplayName( name, canDraw ) ) )
			.Concat( GameLanguage.FanTranslations.Keys.Select( name => string.Format( Get( OpenTpwText.FanTranslation, language ), DisplayName( name, canDraw ) ) ) );

	private static readonly Dictionary<string, HashSet<char>> drawable = new( StringComparer.Ordinal );

	/// <summary>
	/// The characters the language's interface draws: its character table's, less those its body font (GAME8AA) draws no glyph for. The Hebrew
	/// fonts lack the accented Latin letters of their table, so "Français" shows as "French" there.
	/// </summary>
	public static HashSet<char> DrawableCharacters( GameLanguage language )
	{
		lock ( drawable )
		{
			if ( drawable.TryGetValue( language.Directory, out var known ) )
				return known;
			var characters = new HashSet<char>( language.CharacterTable.Characters );
			try { characters.IntersectWith( language.LoadFont( "GAME8AA.bf4" ).Glyphs.Where( glyph => glyph.Width > 0 && glyph.Height > 0 || char.IsWhiteSpace( glyph.Character ) ).Select( glyph => glyph.Character ) ); }
			catch ( Exception exception ) when ( exception is IOException or InvalidDataException ) { }
			return drawable[language.Directory] = characters;
		}
	}
